import { describe, expect, it, vi } from 'vitest';
import { TiledCoverageStore, TiledPixelStore } from '@freetoshop/pixel-storage';
import {
  createSelectionMask,
  DocumentInvariantError,
  addAlphaChannelFromSelection,
  addLayer,
  addLayerRasterMaskFromSelection,
  combineSelection,
  combineRectangularSelection,
  createDocument,
  createAdjustmentLayer,
  createAlphaChannel,
  createGroupLayer,
  createPixelLayer,
  createRasterMask,
  createRasterMaskFromCoverageStore,
  createShapeLayer,
  createSmartObjectLayer,
  createTextLayer,
  createVectorMask,
  duplicateLayer,
  convertLayerToSmartObject,
  createRectangularSelection,
  cropDocument,
  findLayerWorldTransform,
  findLayer,
  findAlphaChannel,
  identityLayerTransform,
  groupLayers,
  invertLayerTransform,
  invertSelection,
  invertLayerMask,
  invertLayerVectorMask,
  multiplyLayerTransforms,
  patchPixels,
  patchLayerRasterMask,
  loadAlphaChannelSelection,
  removeLayer,
  replaceRootLayers,
  replacePixelStore,
  replaceSmartObjectSource,
  removeAlphaChannel,
  renameLayer,
  renameAlphaChannel,
  resizeCanvas,
  revealAll,
  reorderLayer,
  setLayerOpacity,
  setLayerBlendMode,
  setLayerClipping,
  setLayerFillOpacity,
  setLayerEffects,
  setLayerLock,
  setLayerLocks,
  setGroupCompositing,
  setAdjustmentLayerParameters,
  setLayerMaskDensity,
  setLayerMaskEnabled,
  setLayerRasterMask,
  setLayerVectorMask,
  setLayerVectorMaskDensity,
  setLayerVectorMaskEnabled,
  setLayerTransform,
  setLayerTranslation,
  setSelection,
  setShapeGeometry,
  setShapeStyle,
  setSmartObjectFilters,
  setTextContent,
  setTextStyle,
  setLayerVisibility,
  selectAll,
  transformPoint,
  ungroupLayer,
  addDocumentGuide,
  removeDocumentGuide,
  moveDocumentGuide,
  clearDocumentGuides,
  type SelectionCombineMode,
} from './index.js';

const pixel = (id: string) => createPixelLayer({ id, name: id, width: 2, height: 2 });

describe('document model', () => {
  it('owns editable shape and text data and applies structured edit commands immutably', () => {
    const fill = { red: 10, green: 20, blue: 30, alpha: 255 };
    const shape = createShapeLayer({
      id: 'shape',
      name: 'Shape',
      geometry: { type: 'rectangle', width: 20, height: 10, cornerRadius: 2 },
      style: { fill },
    });
    const text = createTextLayer({
      id: 'text',
      name: 'Text',
      text: 'Hello',
      width: 100,
      height: 40,
    });
    fill.red = 200;
    expect(shape.style.fill?.red).toBe(10);

    const original = createDocument({
      id: 'structured',
      name: 'Structured',
      width: 200,
      height: 100,
      layers: [shape, text],
    });
    const editedShape = setShapeStyle('shape', {
      fill: { red: 255, green: 0, blue: 0, alpha: 255 },
      stroke: null,
      strokeWidth: 0,
    }).execute(
      setShapeGeometry('shape', {
        type: 'ellipse',
        width: 30,
        height: 15,
        cornerRadius: 0,
        commands: [],
      }).execute(original),
    );
    const editedText = setTextStyle('text', {
      ...text.style,
      fontSize: 24,
      align: 'center',
    }).execute(setTextContent('text', 'Edited').execute(editedShape));

    expect(findLayer(original, 'shape')).toEqual(shape);
    expect(findLayer(editedText, 'shape')).toMatchObject({
      kind: 'shape',
      geometry: { type: 'ellipse', width: 30, height: 15 },
    });
    expect(findLayer(editedText, 'text')).toMatchObject({
      kind: 'text',
      text: 'Edited',
      style: { fontSize: 24, align: 'center' },
    });
  });

  it('rejects invalid structured geometry and style values', () => {
    expect(() =>
      createShapeLayer({
        id: 'shape',
        name: 'Shape',
        geometry: { width: 0, height: 10 },
      }),
    ).toThrow(DocumentInvariantError);
    expect(() =>
      createTextLayer({
        id: 'text',
        name: 'Text',
        width: 10,
        height: 10,
        style: { fontSize: 0 },
      }),
    ).toThrow(DocumentInvariantError);
  });

  it('owns and validates editable line and cubic vector paths', () => {
    const commands = [
      { type: 'move' as const, x: 1, y: 1 },
      { type: 'line' as const, x: 9, y: 1 },
      {
        type: 'cubic' as const,
        control1X: 10,
        control1Y: 3,
        control2X: 7,
        control2Y: 9,
        x: 1,
        y: 9,
      },
      { type: 'close' as const },
    ];
    const layer = createShapeLayer({
      id: 'path',
      name: 'Path',
      geometry: { type: 'path', width: 10, height: 10, cornerRadius: 0, commands },
    });
    commands[1] = { type: 'line', x: 2, y: 2 };
    expect(layer.geometry.commands[1]).toEqual({ type: 'line', x: 9, y: 1 });

    expect(() =>
      createShapeLayer({
        id: 'bad-path',
        name: 'Bad path',
        geometry: {
          type: 'path',
          width: 10,
          height: 10,
          cornerRadius: 0,
          commands: [
            { type: 'line', x: 1, y: 1 },
            { type: 'line', x: 2, y: 2 },
          ],
        },
      }),
    ).toThrow('begin with a move command');
    expect(() =>
      createShapeLayer({
        id: 'bad-rectangle',
        name: 'Bad rectangle',
        geometry: {
          type: 'rectangle',
          width: 10,
          height: 10,
          cornerRadius: 0,
          commands: [
            { type: 'move', x: 0, y: 0 },
            { type: 'line', x: 1, y: 1 },
          ],
        },
      }),
    ).toThrow('Only path shapes');
  });

  it('owns, validates, and edits nondestructive layer effects', () => {
    const layer = createPixelLayer({
      id: 'effected',
      name: 'Effected',
      width: 1,
      height: 1,
      effects: [
        {
          type: 'drop-shadow',
          enabled: true,
          opacity: 0.5,
          offsetX: 2,
          offsetY: 3,
          blur: 4,
          color: { red: 0, green: 0, blue: 0, alpha: 255 },
        },
      ],
    });
    const document = createDocument({
      id: 'doc',
      name: 'Doc',
      width: 4,
      height: 4,
      layers: [layer],
    });
    const next = setLayerEffects('effected', [
      {
        type: 'color-overlay',
        enabled: true,
        opacity: 1,
        blendMode: 'normal',
        color: { red: 255, green: 0, blue: 0, alpha: 255 },
      },
    ]).execute(document);
    expect(findLayer(document, 'effected')?.effects[0]?.type).toBe('drop-shadow');
    expect(findLayer(next, 'effected')?.effects[0]?.type).toBe('color-overlay');
    expect(() =>
      createPixelLayer({
        id: 'bad',
        name: 'Bad',
        width: 1,
        height: 1,
        effects: [
          {
            type: 'stroke',
            enabled: true,
            opacity: 1,
