/**
 * Samples a clone stamp source region in document space and returns the smallest layer-local
 * patch containing changed pixels. The source is sampled from the provided source layer at the
 * given document-space source point; the source layer is not mutated.
 *
 * In aligned mode the first destination click establishes an offset that is preserved for every
 * subsequent dab. In unaligned mode every dab re-samples the same source point.
 */
export function cloneStampStroke(
  sourceLayer: PixelLayer,
  sourceTransform: LayerTransform,
  destinationLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  sourcePoint: { readonly x: number; readonly y: number },
  selection?: SelectionMask | null,
): PixelPatch {
  validateLayer(sourceLayer);
  validateLayer(destinationLayer);
  validateTransform(sourceTransform);
  validateSelection(selection);
  if (points.length === 0) throw new RangeError('Stroke must contain at least one point');
  assertFinite(options.size, 'Clone stamp brush size');
  if (options.size <= 0) throw new RangeError('Brush size must be greater than 0');
  assertUnit(options.hardness, 'Clone stamp brush hardness');
  assertUnit(options.opacity, 'Clone stamp brush opacity');
  const mode: unknown = options.mode;
  if (mode !== 'source-over' && mode !== 'erase') {
    throw new RangeError('Clone stamp mode must be source-over or erase');
  }
  const firstPoint = points[0];
  // In aligned mode, the source point is offset from the first destination click by a fixed amount.
  // In unaligned mode, every dab uses the same document-space source point.
  const offsetDx = options.aligned ? sourcePoint.x - firstPoint.x : 0;
  const offsetDy = options.aligned ? sourcePoint.y - firstPoint.y : 0;

  const radius = options.size / 2;
  const destInverse = invertTransform(destinationLayer.transform);
  const sourceInverse = invertTransform(sourceTransform);

  // Interpolate dabs with spacing to match paintStroke behavior.
  const spacing = Math.max(0.25, radius * 0.5);
  const dabs: Array<{ x: number; y: number; pressure: number }> = [
    { x: firstPoint.x, y: firstPoint.y, pressure: firstPoint.pressure ?? 1 },
  ];
  for (let index = 1; index < points.length; index += 1) {
    const start = points[index - 1];
    const end = points[index];
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const steps = Math.max(1, Math.ceil(distance / spacing));
    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      dabs.push({
        x: start.x + (end.x - start.x) * progress,
        y: start.y + (end.y - start.y) * progress,
        pressure: (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
      });
    }
  }

  // Compute working bounds in destination layer space.
  let strokeBounds: Bounds | null = null;
  for (const dab of dabs) {
    strokeBounds = unionBounds(
      strokeBounds,
      localDabBounds(
        destinationLayer.transform,
        destInverse,
        dab.x,
        dab.y,
        radius,
        destinationLayer.width,
        destinationLayer.height,
      ),
    );
  }
  if (strokeBounds === null || strokeBounds.right < strokeBounds.left) {
    return emptyPatch();
  }

  // Read source pixels for the union of all mapped source regions.
  // For each dab, the source document point is sourcePoint + aligned_offset_from_first_dab.
  let sourceBounds: Bounds | null = null;
  for (const dab of dabs) {
    const docSourceX = options.aligned
      ? sourcePoint.x + (dab.x - firstPoint.x)
      : sourcePoint.x;
    const docSourceY = options.aligned
      ? sourcePoint.y + (dab.y - firstPoint.y)
      : sourcePoint.y;
    const localX = sourceInverse.a * docSourceX + sourceInverse.c * docSourceY + sourceInverse.e;
    const localY = sourceInverse.b * docSourceX + sourceInverse.d * docSourceY + sourceInverse.f;
    const extentX = radius * Math.hypot(sourceInverse.a, sourceInverse.c);
    const extentY = radius * Math.hypot(sourceInverse.b, sourceInverse.d);
    sourceBounds = unionBounds(
      sourceBounds,
      {
        left: Math.max(0, Math.ceil(localX - extentX)),
        top: Math.max(0, Math.ceil(localY - extentY)),
        right: Math.min(sourceLayer.width - 1, Math.floor(localX + extentX)),
        bottom: Math.min(sourceLayer.height - 1, Math.floor(localY + extentY)),
      },
    );
  }
  if (sourceBounds === null || sourceBounds.right < sourceBounds.left) {
    return emptyPatch();
  }

  const sourceReadWidth = sourceBounds.right - sourceBounds.left + 1;
  const sourceReadHeight = sourceBounds.bottom - sourceBounds.top + 1;
  const sourceBuffer = sourceLayer.pixelStore.read({
    x: sourceBounds.left,
    y: sourceBounds.top,
    width: sourceReadWidth,
    height: sourceReadHeight,
  });

  const regionLeft = strokeBounds.left;
  const regionTop = strokeBounds.top;
  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
  const next = destinationLayer.pixelStore.read({
    x: regionLeft,
    y: regionTop,
    width: regionWidth,
    height: regionHeight,
  });
  const selectionRegion = readSelectionRegion(selection, dabs, radius);
  let changedBounds: Bounds | null = null;

  for (const dab of dabs) {
    const destBounds = localDabBounds(
      destinationLayer.transform,
      destInverse,
      dab.x,
      dab.y,
      radius,
      destinationLayer.width,
      destinationLayer.height,
    );
    const { left, top, right, bottom } = destBounds;
    for (let y = top; y <= bottom; y += 1) {
      for (let x = left; x <= right; x += 1) {
        const documentPoint = transformPoint(destinationLayer.transform, x, y);
        // Compute the source document point for this dab.
        const docSourceX = options.aligned
          ? sourcePoint.x + (dab.x - firstPoint.x)
          : sourcePoint.x;
        const docSourceY = options.aligned
          ? sourcePoint.y + (dab.y - firstPoint.y)
          : sourcePoint.y;
        // Map source document point to source layer-local space.
        const sourceLocalX = Math.round(
          sourceInverse.a * docSourceX + sourceInverse.c * docSourceY + sourceInverse.e,
        );
        const sourceLocalY = Math.round(
          sourceInverse.b * docSourceX + sourceInverse.d * docSourceY + sourceInverse.f,
        );
        const clampedSourceX = clampIndex(sourceLocalX, sourceLayer.width - 1);
        const clampedSourceY = clampIndex(sourceLocalY, sourceLayer.height - 1);
        // Map to buffer coordinates.
        const bufferX = clampedSourceX - sourceBounds.left;
        const bufferY = clampedSourceY - sourceBounds.top;
        const sourceOffset = (bufferY * sourceReadWidth + bufferX) * 4;
        const sampledRed = sourceBuffer[sourceOffset] ?? 0;
        const sampledGreen = sourceBuffer[sourceOffset + 1] ?? 0;
        const sampledBlue = sourceBuffer[sourceOffset + 2] ?? 0;
        const sampledAlpha = sourceBuffer[sourceOffset + 3] ?? 0;

        const falloff = dabCoverage(
          Math.hypot(documentPoint.x - dab.x, documentPoint.y - dab.y),
          radius,
          options.hardness,
        );
        const selected = selectionCoverage(
          selection,
          documentPoint.x,
          documentPoint.y,
          selectionRegion.buffer,
          selectionRegion.region,
        );
        const coverage = falloff * options.opacity * dab.pressure * selected;
        if (coverage <= 0) continue;
        const offset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
        const before = [next[offset], next[offset + 1], next[offset + 2], next[offset + 3]];
        if (options.mode === 'erase') {
          next[offset + 3] = Math.round((next[offset + 3] ?? 0) * (1 - coverage));
        } else {
          compositeSourceOver(next, offset, [sampledRed, sampledGreen, sampledBlue, sampledAlpha], coverage);
        }
        if (
          before[0] !== next[offset] ||
          before[1] !== next[offset + 1] ||
          before[2] !== next[offset + 2] ||
          before[3] !== next[offset + 3]
        ) {
          changedBounds = include(changedBounds, x, y);
        }
      }
    }
  }
  return makePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
}

