  points: readonly BrushPoint[],
  options: CloneStampOptions,
  sourcePoint: { readonly x: number; readonly y: number },
  selection?: SelectionMask | null,
): PixelPatch {
  validateLayer(sourceLayer);
  validateLayer(destinationLayer);
  validateTransform(sourceTransform);
  validateTransform(destinationLayer.transform);
  validateSelection(selection);
  if (points.length === 0) throw new RangeError('Stroke must contain at least one point');
  assertFinite(options.size, 'Clone stamp brush size');
  if (options.size <= 0) throw new RangeError('Brush size must be greater than 0');
  assertUnit(options.hardness, 'Clone stamp brush hardness');
  assertUnit(options.opacity, 'Clone stamp brush opacity');
  const mode: unknown = options.mode;
  if (mode !== 'source-over' && mode !== 'erase') {
    throw new RangeError('Clone stamp mode must be source-over or erase');
  }
  const firstPoint = points[0];
  // Compute the per-dab source offset.
  const offsetDx = sourcePoint.x - firstPoint.x;
  const offsetDy = sourcePoint.y - firstPoint.y;
  const effectiveSourcePoint = options.aligned
    ? { x: sourcePoint.x, y: sourcePoint.y }
    : { x: sourcePoint.x + offsetDx, y: sourcePoint.y + offsetDy };

  // Build a temporary "source layer" that covers just the dab region.
  // We sample from the source layer's pixelStore using inverse mapping.
  const radius = options.size / 2;
  const destInverse = invertTransform(destinationLayer.transform);
  const sourceInverse = invertTransform(sourceTransform);

  // Determine the working bounds in destination layer space.
  let destBounds: Bounds | null = null;
  for (const point of points) {
    destBounds = unionBounds(
      destBounds,
      localDabBounds(
        destinationLayer.transform,
        destInverse,
        point.x,
        point.y,
        radius,
        destinationLayer.width,
        destinationLayer.height,
      ),
    );
  }
  if (destBounds === null || destBounds.right < destBounds.left) {
    return emptyPatch();
  }

  // Read source pixels at the mapped positions.
  const sourceRegionWidth = destBounds.right - destBounds.left + 1;
  const sourceRegionHeight = destBounds.bottom - destBounds.top + 1;
  const sourceBuffer = sourceLayer.pixelStore.read({
    x: Math.max(0, destBounds.left),
    y: Math.max(0, destBounds.top),
    width: Math.min(sourceRegionWidth, sourceLayer.width - Math.max(0, destBounds.left)),
    height: Math.min(sourceRegionHeight, sourceLayer.height - Math.max(0, destBounds.top)),
  });

  // Compute the patch in destination layer space.
  const patchWidth = destBounds.right - destBounds.left + 1;
  const patchHeight = destBounds.bottom - destBounds.top + 1;
  const patchPixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);

  // Sample from source and write to destination.
  for (let y = destBounds.top; y <= destBounds.bottom; y += 1) {
    for (let x = destBounds.left; x <= destBounds.right; x += 1) {
      const destPoint = transformPoint(destinationLayer.transform, x, y);
      const sampledX = options.aligned
        ? effectiveSourcePoint.x - (destPoint.x - firstPoint.x)
        : effectiveSourcePoint.x;
      const sampledY = options.aligned
        ? effectiveSourcePoint.y - (destPoint.y - firstPoint.y)
        : effectiveSourcePoint.y;

      const sourceLocalX = Math.round(
        sourceInverse.a * sampledX + sourceInverse.c * sampledY + sourceInverse.e,
      );
      const sourceLocalY = Math.round(
        sourceInverse.b * sampledX + sourceInverse.d * sampledY + sourceInverse.f,
      );
      const clampedSourceX = clampIndex(sourceLocalX, sourceLayer.width - 1);
      const clampedSourceY = clampIndex(sourceLocalY, sourceLayer.height - 1);
      const sourceOffset = (clampedSourceY * sourceLayer.width + clampedSourceX) * 4;
      const sampledRed = sourceBuffer[sourceOffset] ?? 0;
      const sampledGreen = sourceBuffer[sourceOffset + 1] ?? 0;
      const sampledBlue = sourceBuffer[sourceOffset + 2] ?? 0;
      const sampledAlpha = sourceBuffer[sourceOffset + 3] ?? 0;

      const falloff = dabCoverage(
        Math.hypot(destPoint.x - (options.aligned ? firstPoint.x + (sampledX - effectiveSourcePoint.x) : effectiveSourcePoint.x),
                   destPoint.y - (options.aligned ? firstPoint.y + (sampledY - effectiveSourcePoint.y) : effectiveSourcePoint.y)),
        radius,
        options.hardness,
      );
      const selected = selectionCoverage(selection, destPoint.x, destPoint.y);
      const coverage = falloff * options.opacity * selected;
      if (coverage <= 0) continue;

      const patchOffset = ((y - destBounds.top) * patchWidth + (x - destBounds.left)) * 4;
      const before = [
        patchPixels[patchOffset] ?? 0,
        patchPixels[patchOffset + 1] ?? 0,
        patchPixels[patchOffset + 2] ?? 0,
        patchPixels[patchOffset + 3] ?? 0,
      ];
      if (options.mode === 'erase') {
        patchPixels[patchOffset + 3] = Math.round((patchPixels[patchOffset + 3] ?? 0) * (1 - coverage));
      } else {
        compositeSourceOver(
          patchPixels,
          patchOffset,
          [sampledRed, sampledGreen, sampledBlue, sampledAlpha] as [number, number, number, number],
          coverage,
        );
      }
      if (
        before[0] !== patchPixels[patchOffset] ||
        before[1] !== patchPixels[patchOffset + 1] ||
        before[2] !== patchPixels[patchOffset + 2] ||
        before[3] !== patchPixels[patchOffset + 3]
      ) {
        // Track changed bounds.
      }
    }
  }

  // Find changed bounds.
  let changedBounds: Bounds | null = null;
  for (let y = destBounds.top; y <= destBounds.bottom; y += 1) {
    for (let x = destBounds.left; x <= destBounds.right; x += 1) {
      const offset = ((y - destBounds.top) * patchWidth + (x - destBounds.left)) * 4;
      if (patchPixels[offset + 3] !== 0) {
        changedBounds = include(changedBounds, x, y);
      }
    }
  }

  return makePatchFromRegion(destBounds.left, destBounds.top, patchWidth, patchPixels, changedBounds);
}

