} else if (
  (tool === 'brush' || tool === 'eraser') &&
  selectedLayer &&
  (selectedLayer.kind === 'pixel' ||
    (editTarget === 'mask' && selectedLayer.kind !== 'adjustment'))
) {
  if (editTarget === 'mask' && selectedLayer.rasterMask === null) {
    notify('Add a raster mask before painting the mask.', 'error');
    return;
  }
  gestureRef.current = {
    kind: 'paint',
    layerId: selectedLayer.id,
    target: editTarget,
    points: [
      { ...point, pressure: event.pointerType === 'pen' ? event.pressure || 1 : 1 },
    ],
  };
} else if (tool === 'clone' && selectedLayer && document) {
  if (event.altKey) {
    setCloneSource({ x: point.x, y: point.y, layerId: selectedLayer.id });
    return;
  }
  if (selectedLayer.kind !== 'pixel') {
    notify('Select a pixel layer to clone from.', 'error');
    return;
  }
  if (!cloneSource) {
    notify('Set a clone source with Alt-click first.', 'error');
    return;
  }
  gestureRef.current = {
    kind: 'clone',
    layerId: selectedLayer.id,
    points: [
      { ...point, pressure: event.pointerType === 'pen' ? event.pressure || 1 : 1 },
    ],
    source: { x: cloneSource.x, y: cloneSource.y },
  };
} else {
  notify('Select a pixel layer or an editable layer mask before painting.', 'error');
}

