        { x: 8, y: 5 },
      ],
      baseOptions,
      { x: 7, y: 5 },
    );
    expect(patch.width).toBeGreaterThan(0);
    // Both dabs should use the same offset (0) from source point.
    const hasBlue = patch.pixels.some((v, i) => i % 4 === 2 && v === 255);
    expect(hasBlue).toBe(true);
  });

