      ],
      unalignedOptions,
      { x: 7, y: 5 },
    );
    expect(patch.width).toBeGreaterThan(0);
    // In unaligned mode, every dab samples from source point (7,5) which is blue.
    const hasBlue = patch.pixels.some((v, i) => i % 4 === 2 && v === 255);
    expect(hasBlue).toBe(true);
  });

  it('returns a no-op for empty points', () => {
