+      id: 'huge-source',
+      name: 'Huge Source',
+      width: 4096,
+      height: 4096,
+    });
+    const hugeDest = createPixelLayer({
+      id: 'huge-dest',
+      name: 'Huge Dest',
+      width: 4096,
+      height: 4096,
+    });
+    const beforeBytes = hugeDest.pixelStore.allocatedByteLength;
