it('is tile-local on large sparse layers', () => {
  const hugeSource = createPixelLayer({
    id: 'huge-source',
    name: 'Huge Source',
    width: 4096,
    height: 4096,
    pixels: new Uint8ClampedArray(4096 * 4096 * 4).fill(0),
  });
  // Fill a small region with blue + alpha so sampling works.
  const hugeSourcePixels = hugeSource.pixelStore.toContiguous();
  for (let y = 1990; y < 2010; y++) {
    for (let x = 1990; x < 2010; x++) {
      const offset = (y * 4096 + x) * 4;
      hugeSourcePixels[offset + 2] = 255; // blue
      hugeSourcePixels[offset + 3] = 255; // alpha
    }
  }
  const updatedHugeSource = hugeSource.pixelStore.write({
    x: 0, y: 0, width: 4096, height: 4096,
    pixels: hugeSourcePixels,
  }).store;
  const hugeSourceLayer = { ...hugeSource, pixelStore: updatedHugeSource };
  const hugeDest = createPixelLayer({
    id: 'huge-dest',
    name: 'Huge Dest',
    width: 4096,
    height: 4096,
  });
  const beforeBytes = hugeDest.pixelStore.allocatedByteLength;
  const patch = cloneStampStroke(
    hugeSourceLayer,
    identityTransform,
    hugeDest,
    [{ x: 2000, y: 2000 }],
    { ...baseOptions, size: 16, hardness: 0.85, opacity: 0.9 },
    { x: 2000, y: 2000 },
  );
  expect(patch.width).toBeGreaterThan(0);
  expect(patch.width * patch.height).toBeLessThan(64 * 64);
  // Source layer remains sparse.
  expect(hugeSource.pixelStore.allocatedByteLength).toBe(beforeBytes);
  expect(hugeDest.pixelStore.allocatedByteLength).toBe(beforeBytes);
});

