test('clone stamp respects aligned mode', async ({ page }) => {
  const bytes = await page.evaluate(async () => {
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 32;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas unavailable');
    // Left half red, right half blue for easy verification.
    for (let y = 0; y < 32; y++) {
      for (let x = 0; x < 32; x++) {
        context.fillStyle = x < 16 ? 'rgb(255,0,0)' : 'rgb(0,0,255)';
        context.fillRect(x, y, 1, 1);
      }
    }
    const blob = await new Promise<Blob>((resolve, reject) =>
      canvas.toBlob(
        (value) => (value ? resolve(value) : reject(new Error('PNG failed'))),
        'image/png',
      ),
    );
    return [...new Uint8Array(await blob.arrayBuffer())];
  });
  const sourceBuffer = Buffer.from(bytes);

  await page.getByLabel('Open image file').setInputFiles({
    name: 'clone-aligned.png',
    mimeType: 'image/png',
    buffer: sourceBuffer,
  });

  await page.getByRole('button', { name: 'Clone stamp' }).click();

  // Set source at top-left (red region).
  const sourcePoint = await documentPoint(page, 4, 4);
  await page.mouse.move(sourcePoint.x, sourcePoint.y);
  await page.keyboard.down('Alt');
  await page.mouse.down();
  await page.mouse.up();
  await page.keyboard.up('Alt');

  // Enable aligned mode (default).
  const alignedCheckbox = page.getByRole('checkbox', { name: 'Aligned' });
  await alignedCheckbox.check();

  // Paint at a point offset from source. In aligned mode, the relative offset
  // from the first paint click is preserved.
  const paintStart = await documentPoint(page, 20, 20);
  await page.mouse.move(paintStart.x, paintStart.y);
  await page.mouse.down();
  await page.mouse.move(paintStart.x + 4, paintStart.y + 4);
  await page.mouse.up();

  // With aligned mode, painting at (20,20) samples from source at (4,4) which is red.
  // Painting at (24,24) samples from source at (8,8) which is also red (still in left half).
  expect(await exportedPixel(page, 20, 20)).toEqual([255, 0, 0, 255]);
});

