    }
    const snapshot = value as Record<string, unknown>;
    if (snapshot.schemaVersion !== 1) throw new RangeError('Unsupported tiled pixel snapshot');
    const width = snapshotInteger(snapshot.width, 'Snapshot width');
    const height = snapshotInteger(snapshot.height, 'Snapshot height');
    const tileSize = snapshotInteger(snapshot.tileSize, 'Snapshot tile size');
    validateDimensions(width, height, tileSize);
    if (!Array.isArray(snapshot.tiles)) throw new TypeError('Snapshot tiles must be an array');
    const columnCount = Math.ceil(width / tileSize);
    const rowCount = Math.ceil(height / tileSize);
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [index, tileValue] of snapshot.tiles.entries()) {
      if (typeof tileValue !== 'object' || tileValue === null) {
        throw new TypeError(`Snapshot tile ${String(index)} must be an object`);
      }
      const tile = tileValue as Record<string, unknown>;
      const column = snapshotInteger(tile.column, `Snapshot tile ${String(index)} column`);
      const row = snapshotInteger(tile.row, `Snapshot tile ${String(index)} row`);
      if (column < 0 || row < 0 || column >= columnCount || row >= rowCount) {
        throw new RangeError(`Snapshot tile ${String(index)} is outside the store`);
      }
      const key = tileKey(column, row, columnCount);
      if (tiles.has(key)) throw new RangeError(`Snapshot tile ${String(index)} is duplicated`);
      const tileWidth = Math.min(tileSize, width - column * tileSize);
      const tileHeight = Math.min(tileSize, height - row * tileSize);
      if (!(tile.pixels instanceof Uint8ClampedArray)) {
        throw new TypeError(`Snapshot tile ${String(index)} pixels must be Uint8ClampedArray`);
      }
      if (tile.pixels.length !== tileWidth * tileHeight * 4) {
        throw new RangeError(`Snapshot tile ${String(index)} length does not match its bounds`);
      }
      const owned = new Uint8ClampedArray(tile.pixels);
      if (tileIsTransparent(owned)) {
        throw new RangeError(`Snapshot tile ${String(index)} must not be fully transparent`);
      }
      tiles.set(key, owned);
    }
    return new TiledPixelStore(width, height, tileSize, tiles);
  }

  get tileCount(): number {
    return this.#tiles.size;
  }

  get allocatedByteLength(): number {
    let bytes = 0;
    for (const pixels of this.#tiles.values()) bytes += pixels.byteLength;
    return bytes;
  }

  getTile(column: number, row: number): PixelTile | null {
    integer(column, 'Tile column');
    integer(row, 'Tile row');
    if (column < 0 || row < 0 || column >= this.columnCount || row >= this.rowCount) return null;
    const key = tileKey(column, row, this.columnCount);
    const pixels = this.#tiles.get(key);
    if (!pixels) return null;
    const region = this.tileRegion(column, row);
    return { key, column, row, ...region, pixels };
  }

  *tiles(): IterableIterator<PixelTile> {
    for (const key of [...this.#tiles.keys()].sort((left, right) => left - right)) {
      const column = key % this.columnCount;
      const row = Math.floor(key / this.columnCount);
      const tile = this.getTile(column, row);
      if (tile) yield tile;
    }
  }

  /** Produces an owned, deterministic representation suitable for workers and native containers. */
  snapshot(region?: PixelRegion): TiledPixelStoreSnapshot {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : null;
    return {
      schemaVersion: 1,
      width: this.width,
      height: this.height,
      tileSize: this.tileSize,
      tiles: [...this.tiles()]
        .filter(
          (tile) =>
            region === undefined || (requested !== null && intersectRegions(tile, requested)),
        )
        .map((tile) => ({
          column: tile.column,
          row: tile.row,
          pixels: new Uint8ClampedArray(tile.pixels),
        })),
    };
  }

  *pixelChunks(region?: PixelRegion): IterableIterator<PixelPatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    for (const tile of this.tiles()) {
      if (intersectRegions(tile, requested)) {
        yield { x: tile.x, y: tile.y, width: tile.width, height: tile.height, pixels: tile.pixels };
      }
    }
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height * 4);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    for (const tile of this.pixelChunks(clipped)) {
      const overlap = intersectRegions(tile, clipped);
      if (!overlap) continue;
      for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
        const sourceStart = ((y - tile.y) * tile.width + (overlap.x - tile.x)) * 4;
        const destinationStart = ((y - region.y) * region.width + (overlap.x - region.x)) * 4;
        output.set(
          tile.pixels.subarray(sourceStart, sourceStart + overlap.width * 4),
          destinationStart,
        );
      }
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    const output = new Uint8ClampedArray(this.width * this.height * 4);
    for (const tile of this.tiles()) {
      for (let localY = 0; localY < tile.height; localY += 1) {
        const sourceStart = localY * tile.width * 4;
        const destinationStart = ((tile.y + localY) * this.width + tile.x) * 4;
        output.set(
          tile.pixels.subarray(sourceStart, sourceStart + tile.width * 4),
          destinationStart,
        );
      }
    }
    return output;
  }

  write(patch: PixelPatch): PixelWriteResult {
    validatePatch(patch);
    const clipped = intersectRegions(patch, { x: 0, y: 0, width: this.width, height: this.height });
    if (!clipped) return { store: this, dirtyRegion: null, changedTileKeys: [] };

    const tiles = new Map(this.#tiles);
    const changedKeys: number[] = [];
    let dirtyLeft = this.width;
    let dirtyTop = this.height;
    let dirtyRight = -1;
    let dirtyBottom = -1;
    const firstColumn = Math.floor(clipped.x / this.tileSize);
    const lastColumn = Math.floor((clipped.x + clipped.width - 1) / this.tileSize);
    const firstRow = Math.floor(clipped.y / this.tileSize);
    const lastRow = Math.floor((clipped.y + clipped.height - 1) / this.tileSize);

    for (let row = firstRow; row <= lastRow; row += 1) {
      for (let column = firstColumn; column <= lastColumn; column += 1) {
        const key = tileKey(column, row, this.columnCount);
        const tileRegion = this.tileRegion(column, row);
        const overlap = intersectRegions(clipped, tileRegion);
        if (!overlap) continue;
        const existing = this.#tiles.get(key);
        const next = existing
          ? new Uint8ClampedArray(existing)
          : new Uint8ClampedArray(tileRegion.width * tileRegion.height * 4);
        let tileChanged = false;
        for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
          for (let x = overlap.x; x < overlap.x + overlap.width; x += 1) {
            const sourceOffset = ((y - patch.y) * patch.width + (x - patch.x)) * 4;
            const tileOffset = ((y - tileRegion.y) * tileRegion.width + (x - tileRegion.x)) * 4;
            let pixelChanged = false;
            for (let channel = 0; channel < 4; channel += 1) {
              const value = patch.pixels[sourceOffset + channel] ?? 0;
              if ((next[tileOffset + channel] ?? 0) !== value) {
                next[tileOffset + channel] = value;
                pixelChanged = true;
              }
            }
            if (pixelChanged) {
              tileChanged = true;
              dirtyLeft = Math.min(dirtyLeft, x);
              dirtyTop = Math.min(dirtyTop, y);
              dirtyRight = Math.max(dirtyRight, x);
              dirtyBottom = Math.max(dirtyBottom, y);
            }
          }
        }
        if (!tileChanged) continue;
        changedKeys.push(key);
        if (tileIsTransparent(next)) tiles.delete(key);
        else tiles.set(key, next);
      }
    }

    if (changedKeys.length === 0) return { store: this, dirtyRegion: null, changedTileKeys: [] };
    return {
      store: new TiledPixelStore(this.width, this.height, this.tileSize, tiles),
      dirtyRegion: {
        x: dirtyLeft,
        y: dirtyTop,
        width: dirtyRight - dirtyLeft + 1,
        height: dirtyBottom - dirtyTop + 1,
      },
      changedTileKeys: changedKeys,
    };
  }

  /** Applies an owned worker delta while sharing every unchanged immutable tile. */
  applyTileDelta(delta: TiledPixelStoreDelta): TiledPixelStore {
    const tiles = new Map(this.#tiles);
    const changed = new Set<number>();
    for (const key of delta.removedTileKeys) {
      integer(key, 'Removed pixel tile key');
      if (key < 0 || key >= this.columnCount * this.rowCount || changed.has(key)) {
        throw new RangeError('Removed pixel tile key is invalid or duplicated');
      }
      changed.add(key);
      tiles.delete(key);
    }
    for (const [index, tile] of delta.tiles.entries()) {
      integer(tile.column, `Pixel delta tile ${String(index)} column`);
      integer(tile.row, `Pixel delta tile ${String(index)} row`);
      if (
        tile.column < 0 ||
        tile.row < 0 ||
        tile.column >= this.columnCount ||
        tile.row >= this.rowCount
      ) {
        throw new RangeError(`Pixel delta tile ${String(index)} is outside the store`);
      }
      const key = tileKey(tile.column, tile.row, this.columnCount);
      if (changed.has(key)) throw new RangeError(`Pixel delta tile ${String(index)} is duplicated`);
      changed.add(key);
      const region = this.tileRegion(tile.column, tile.row);
      if (!(tile.pixels instanceof Uint8ClampedArray)) {
        throw new TypeError(`Pixel delta tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.pixels.length !== region.width * region.height * 4) {
        throw new RangeError(`Pixel delta tile ${String(index)} length does not match its bounds`);
      }
      const owned = new Uint8ClampedArray(tile.pixels);
      if (tileIsTransparent(owned)) {
        throw new RangeError(`Pixel delta tile ${String(index)} must not be fully transparent`);
      }
      tiles.set(key, owned);
    }
    return new TiledPixelStore(this.width, this.height, this.tileSize, tiles);
  }

  private tileRegion(column: number, row: number): PixelRegion {
    const x = column * this.tileSize;
    const y = row * this.tileSize;
    return {
      x,
      y,
      width: Math.min(this.tileSize, this.width - x),
      height: Math.min(this.tileSize, this.height - y),
    };
  }
}

/** Immutable sparse one-channel storage for masks, selections, and channels. */
export class TiledCoverageStore implements CoverageSource {
  readonly width: number;
  readonly height: number;
  readonly tileSize: number;
  readonly columnCount: number;
  readonly rowCount: number;
  readonly defaultCoverage: number;
  readonly #tiles: ReadonlyMap<number, Uint8ClampedArray>;

  private constructor(
    width: number,
    height: number,
    tileSize: number,
    defaultCoverage: number,
    tiles: ReadonlyMap<number, Uint8ClampedArray>,
  ) {
    this.width = width;
    this.height = height;
    this.tileSize = tileSize;
    this.columnCount = Math.ceil(width / tileSize);
    this.rowCount = Math.ceil(height / tileSize);
    this.defaultCoverage = defaultCoverage;
    this.#tiles = tiles;
  }

  static empty(width: number, height: number, tileSize = DEFAULT_TILE_SIZE): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    return new TiledCoverageStore(width, height, tileSize, 0, new Map());
  }

  static uniform(
    width: number,
    height: number,
    defaultCoverage: number,
    tileSize = DEFAULT_TILE_SIZE,
  ): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    integer(defaultCoverage, 'Default coverage');
    if (defaultCoverage < 0 || defaultCoverage > 255) {
      throw new RangeError('Default coverage must be between 0 and 255');
    }
    return new TiledCoverageStore(width, height, tileSize, defaultCoverage, new Map());
  }

  static fromContiguous(
    width: number,
    height: number,
    coverage: ArrayLike<number>,
    tileSize = DEFAULT_TILE_SIZE,
  ): TiledCoverageStore {
    validateDimensions(width, height, tileSize);
    if (coverage.length !== width * height) {
      throw new RangeError('Coverage buffer length does not match its dimensions');
    }
    const store = TiledCoverageStore.empty(width, height, tileSize);
    return store.write({
      x: 0,
      y: 0,
      width,
      height,
      coverage: new Uint8ClampedArray(coverage),
    }).store;
  }

  static fromSnapshot(value: unknown): TiledCoverageStore {
    if (typeof value !== 'object' || value === null) {
      throw new TypeError('Tiled coverage snapshot must be an object');
    }
    const snapshot = value as Record<string, unknown>;
    if (snapshot.schemaVersion !== 1 && snapshot.schemaVersion !== 2) {
      throw new RangeError('Unsupported tiled coverage snapshot');
    }
    const width = snapshotInteger(snapshot.width, 'Coverage snapshot width');
    const height = snapshotInteger(snapshot.height, 'Coverage snapshot height');
    const tileSize = snapshotInteger(snapshot.tileSize, 'Coverage snapshot tile size');
    validateDimensions(width, height, tileSize);
    const defaultCoverage =
      snapshot.schemaVersion === 1
        ? 0
        : snapshotInteger(snapshot.defaultCoverage, 'Coverage snapshot default coverage');
    if (defaultCoverage < 0 || defaultCoverage > 255) {
      throw new RangeError('Coverage snapshot default coverage must be between 0 and 255');
    }
    if (!Array.isArray(snapshot.tiles))
      throw new TypeError('Coverage snapshot tiles must be an array');
    const columnCount = Math.ceil(width / tileSize);
    const rowCount = Math.ceil(height / tileSize);
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [index, tileValue] of snapshot.tiles.entries()) {
      if (typeof tileValue !== 'object' || tileValue === null) {
        throw new TypeError(`Coverage snapshot tile ${String(index)} must be an object`);
      }
      const tile = tileValue as Record<string, unknown>;
      const column = snapshotInteger(tile.column, `Coverage snapshot tile ${String(index)} column`);
      const row = snapshotInteger(tile.row, `Coverage snapshot tile ${String(index)} row`);
      if (column < 0 || row < 0 || column >= columnCount || row >= rowCount) {
        throw new RangeError(`Coverage snapshot tile ${String(index)} is outside the store`);
      }
      const key = tileKey(column, row, columnCount);
      if (tiles.has(key))
        throw new RangeError(`Coverage snapshot tile ${String(index)} is duplicated`);
      const tileWidth = Math.min(tileSize, width - column * tileSize);
      const tileHeight = Math.min(tileSize, height - row * tileSize);
      if (!(tile.coverage instanceof Uint8ClampedArray)) {
        throw new TypeError(`Coverage snapshot tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.coverage.length !== tileWidth * tileHeight) {
        throw new RangeError(
          `Coverage snapshot tile ${String(index)} length does not match its bounds`,
        );
      }
      const owned = new Uint8ClampedArray(tile.coverage);
      if (tileIsUniform(owned, defaultCoverage)) {
        throw new RangeError(
          `Coverage snapshot tile ${String(index)} must differ from default coverage`,
        );
      }
      tiles.set(key, owned);
    }
    return new TiledCoverageStore(width, height, tileSize, defaultCoverage, tiles);
  }

  get tileCount(): number {
    return this.#tiles.size;
  }

  get allocatedByteLength(): number {
    let bytes = 0;
    for (const coverage of this.#tiles.values()) bytes += coverage.byteLength;
    return bytes;
  }

  getTile(column: number, row: number): CoverageTile | null {
    integer(column, 'Tile column');
    integer(row, 'Tile row');
    if (column < 0 || row < 0 || column >= this.columnCount || row >= this.rowCount) return null;
    const key = tileKey(column, row, this.columnCount);
    const coverage = this.#tiles.get(key);
    if (!coverage) return null;
    return { key, column, row, ...this.tileRegion(column, row), coverage };
  }

  *tiles(): IterableIterator<CoverageTile> {
    for (const key of [...this.#tiles.keys()].sort((left, right) => left - right)) {
      const tile = this.getTile(key % this.columnCount, Math.floor(key / this.columnCount));
      if (tile) yield tile;
    }
  }

  *coverageChunks(region?: PixelRegion): IterableIterator<CoveragePatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    if (this.defaultCoverage !== 0) {
      const firstColumn = Math.floor(requested.x / this.tileSize);
      const lastColumn = Math.floor((requested.x + requested.width - 1) / this.tileSize);
      const firstRow = Math.floor(requested.y / this.tileSize);
      const lastRow = Math.floor((requested.y + requested.height - 1) / this.tileSize);
      for (let row = firstRow; row <= lastRow; row += 1) {
        for (let column = firstColumn; column <= lastColumn; column += 1) {
          const tile = this.tileRegion(column, row);
          yield { ...tile, coverage: this.read(tile) };
        }
      }
      return;
    }
    for (const tile of this.tiles()) {
      if (intersectRegions(tile, requested)) {
        yield {
          x: tile.x,
          y: tile.y,
          width: tile.width,
          height: tile.height,
          coverage: tile.coverage,
        };
      }
    }
  }

  /** Inverts the implicit default and each deviation tile without visiting missing tiles. */
  invert(): TiledCoverageStore {
    const tiles = new Map<number, Uint8ClampedArray>();
    for (const [key, source] of this.#tiles) {
      const coverage = new Uint8ClampedArray(source.length);
      for (let index = 0; index < coverage.length; index += 1) {
        coverage[index] = 255 - (source[index] ?? this.defaultCoverage);
      }
      tiles.set(key, coverage);
    }
    return new TiledCoverageStore(
      this.width,
      this.height,
      this.tileSize,
      255 - this.defaultCoverage,
      tiles,
    );
  }

  snapshot(region?: PixelRegion): TiledCoverageStoreSnapshot {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : null;
    return {
      schemaVersion: 2,
      width: this.width,
      height: this.height,
      tileSize: this.tileSize,
      defaultCoverage: this.defaultCoverage,
      tiles: [...this.tiles()]
        .filter(
          (tile) =>
            region === undefined || (requested !== null && intersectRegions(tile, requested)),
        )
        .map((tile) => ({
          column: tile.column,
          row: tile.row,
          coverage: new Uint8ClampedArray(tile.coverage),
        })),
    };
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    if (this.defaultCoverage !== 0) {
      for (let y = clipped.y; y < clipped.y + clipped.height; y += 1) {
        const destinationStart = (y - region.y) * region.width + clipped.x - region.x;
        output.fill(this.defaultCoverage, destinationStart, destinationStart + clipped.width);
      }
    }
    for (const tile of this.tiles()) {
      const overlap = intersectRegions(tile, clipped);
      if (!overlap) continue;
      for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
        const sourceStart = (y - tile.y) * tile.width + overlap.x - tile.x;
        const destinationStart = (y - region.y) * region.width + overlap.x - region.x;
        output.set(
          tile.coverage.subarray(sourceStart, sourceStart + overlap.width),
          destinationStart,
        );
      }
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    return this.read({ x: 0, y: 0, width: this.width, height: this.height });
  }

  write(patch: CoveragePatch): CoverageWriteResult {
    validateCoveragePatch(patch);
    const clipped = intersectRegions(patch, { x: 0, y: 0, width: this.width, height: this.height });
    if (!clipped) return { store: this, dirtyRegion: null, changedTileKeys: [] };
    const tiles = new Map(this.#tiles);
    const changedTileKeys: number[] = [];
    let dirtyLeft = this.width;
    let dirtyTop = this.height;
    let dirtyRight = -1;
    let dirtyBottom = -1;
    const firstColumn = Math.floor(clipped.x / this.tileSize);
    const lastColumn = Math.floor((clipped.x + clipped.width - 1) / this.tileSize);
    const firstRow = Math.floor(clipped.y / this.tileSize);
    const lastRow = Math.floor((clipped.y + clipped.height - 1) / this.tileSize);
    for (let row = firstRow; row <= lastRow; row += 1) {
      for (let column = firstColumn; column <= lastColumn; column += 1) {
        const key = tileKey(column, row, this.columnCount);
        const tileRegion = this.tileRegion(column, row);
        const overlap = intersectRegions(clipped, tileRegion);
        if (!overlap) continue;
        const existing = this.#tiles.get(key);
        const next = existing
          ? new Uint8ClampedArray(existing)
          : new Uint8ClampedArray(tileRegion.width * tileRegion.height).fill(this.defaultCoverage);
        let tileChanged = false;
        for (let y = overlap.y; y < overlap.y + overlap.height; y += 1) {
          for (let x = overlap.x; x < overlap.x + overlap.width; x += 1) {
            const sourceOffset = (y - patch.y) * patch.width + x - patch.x;
            const tileOffset = (y - tileRegion.y) * tileRegion.width + x - tileRegion.x;
            const value = patch.coverage[sourceOffset] ?? 0;
            if ((next[tileOffset] ?? 0) === value) continue;
            next[tileOffset] = value;
            tileChanged = true;
            dirtyLeft = Math.min(dirtyLeft, x);
            dirtyTop = Math.min(dirtyTop, y);
            dirtyRight = Math.max(dirtyRight, x);
            dirtyBottom = Math.max(dirtyBottom, y);
          }
        }
        if (!tileChanged) continue;
        changedTileKeys.push(key);
        if (tileIsUniform(next, this.defaultCoverage)) tiles.delete(key);
        else tiles.set(key, next);
      }
    }
    if (changedTileKeys.length === 0) {
      return { store: this, dirtyRegion: null, changedTileKeys: [] };
    }
    return {
      store: new TiledCoverageStore(
        this.width,
        this.height,
        this.tileSize,
        this.defaultCoverage,
        tiles,
      ),
      dirtyRegion: {
        x: dirtyLeft,
        y: dirtyTop,
        width: dirtyRight - dirtyLeft + 1,
        height: dirtyBottom - dirtyTop + 1,
      },
      changedTileKeys,
    };
  }

  /** Applies an owned worker delta while sharing every unchanged immutable tile. */
  applyTileDelta(delta: TiledCoverageStoreDelta): TiledCoverageStore {
    const tiles = new Map(this.#tiles);
    const changed = new Set<number>();
    for (const key of delta.removedTileKeys) {
      integer(key, 'Removed coverage tile key');
      if (key < 0 || key >= this.columnCount * this.rowCount || changed.has(key)) {
        throw new RangeError('Removed coverage tile key is invalid or duplicated');
      }
      changed.add(key);
      tiles.delete(key);
    }
    for (const [index, tile] of delta.tiles.entries()) {
      integer(tile.column, `Coverage delta tile ${String(index)} column`);
      integer(tile.row, `Coverage delta tile ${String(index)} row`);
      if (
        tile.column < 0 ||
        tile.row < 0 ||
        tile.column >= this.columnCount ||
        tile.row >= this.rowCount
      ) {
        throw new RangeError(`Coverage delta tile ${String(index)} is outside the store`);
      }
      const key = tileKey(tile.column, tile.row, this.columnCount);
      if (changed.has(key)) {
        throw new RangeError(`Coverage delta tile ${String(index)} is duplicated`);
      }
      changed.add(key);
      const region = this.tileRegion(tile.column, tile.row);
      if (!(tile.coverage instanceof Uint8ClampedArray)) {
        throw new TypeError(`Coverage delta tile ${String(index)} must use Uint8ClampedArray`);
      }
      if (tile.coverage.length !== region.width * region.height) {
        throw new RangeError(`Coverage delta tile ${String(index)} length does not match bounds`);
      }
      const owned = new Uint8ClampedArray(tile.coverage);
      if (tileIsUniform(owned, this.defaultCoverage)) {
        throw new RangeError(`Coverage delta tile ${String(index)} must differ from default`);
      }
      tiles.set(key, owned);
    }
    return new TiledCoverageStore(
      this.width,
      this.height,
      this.tileSize,
      this.defaultCoverage,
      tiles,
    );
  }

  private tileRegion(column: number, row: number): PixelRegion {
    const x = column * this.tileSize;
    const y = row * this.tileSize;
    return {
      x,
      y,
      width: Math.min(this.tileSize, this.width - x),
      height: Math.min(this.tileSize, this.height - y),
    };
  }
}

export class ContiguousPixelSource implements PixelSource {
  readonly width: number;
  readonly height: number;
  readonly #pixels: Uint8ClampedArray;

  constructor(width: number, height: number, pixels: ArrayLike<number>) {
    validateDimensions(width, height, DEFAULT_TILE_SIZE);
    if (pixels.length !== width * height * 4) {
      throw new RangeError('Pixel buffer length does not match its dimensions');
    }
    this.width = width;
    this.height = height;
    this.#pixels = new Uint8ClampedArray(pixels);
  }

  get allocatedByteLength(): number {
    return this.#pixels.byteLength;
  }

  *pixelChunks(region?: PixelRegion): IterableIterator<PixelPatch> {
    const requested = region
      ? intersectRegions(region, { x: 0, y: 0, width: this.width, height: this.height })
      : { x: 0, y: 0, width: this.width, height: this.height };
    if (!requested) return;
    yield { ...requested, pixels: this.read(requested) };
  }

  read(region: PixelRegion): Uint8ClampedArray {
    validateReadRegion(region);
    const output = new Uint8ClampedArray(region.width * region.height * 4);
    const clipped = intersectRegions(region, {
      x: 0,
      y: 0,
      width: this.width,
      height: this.height,
    });
    if (!clipped) return output;
    for (let y = clipped.y; y < clipped.y + clipped.height; y += 1) {
      const sourceStart = (y * this.width + clipped.x) * 4;
      const destinationStart = ((y - region.y) * region.width + (clipped.x - region.x)) * 4;
      output.set(
        this.#pixels.subarray(sourceStart, sourceStart + clipped.width * 4),
        destinationStart,
      );
    }
    return output;
  }

  toContiguous(): Uint8ClampedArray {
    return new Uint8ClampedArray(this.#pixels);
  }
}

export function intersectRegions(left: PixelRegion, right: PixelRegion): PixelRegion | null {
  const x = Math.max(left.x, right.x);
  const y = Math.max(left.y, right.y);
  const rightEdge = Math.min(left.x + left.width, right.x + right.width);
  const bottomEdge = Math.min(left.y + left.height, right.y + right.height);
  return rightEdge <= x || bottomEdge <= y
    ? null
    : { x, y, width: rightEdge - x, height: bottomEdge - y };
}

export function unionRegions(
  left: PixelRegion | null,
  right: PixelRegion | null,
): PixelRegion | null {
  if (!left) return right ? { ...right } : null;
  if (!right) return { ...left };
  const x = Math.min(left.x, right.x);
  const y = Math.min(left.y, right.y);
  const rightEdge = Math.max(left.x + left.width, right.x + right.width);
  const bottomEdge = Math.max(left.y + left.height, right.y + right.height);
  return { x, y, width: rightEdge - x, height: bottomEdge - y };
}

function regionsTouch(left: PixelRegion, right: PixelRegion): boolean {
  return (
    left.x <= right.x + right.width &&
    right.x <= left.x + left.width &&
    left.y <= right.y + right.height &&
    right.y <= left.y + left.height
  );
}

function validateDimensions(width: number, height: number, tileSize: number): void {
  positiveInteger(width, 'Pixel store width');
  positiveInteger(height, 'Pixel store height');
  positiveInteger(tileSize, 'Tile size');
  if (tileSize > MAX_TILE_SIZE)
    throw new RangeError(`Tile size cannot exceed ${String(MAX_TILE_SIZE)}`);
}

function validatePatch(patch: PixelPatch): void {
  integer(patch.x, 'Patch x');
  integer(patch.y, 'Patch y');
  positiveInteger(patch.width, 'Patch width');
  positiveInteger(patch.height, 'Patch height');
  if (patch.pixels.length !== patch.width * patch.height * 4) {
    throw new RangeError('Patch pixel length does not match its dimensions');
  }
}

function validateCoveragePatch(patch: CoveragePatch): void {
  integer(patch.x, 'Coverage patch x');
  integer(patch.y, 'Coverage patch y');
  positiveInteger(patch.width, 'Coverage patch width');
  positiveInteger(patch.height, 'Coverage patch height');
  if (patch.coverage.length !== patch.width * patch.height) {
    throw new RangeError('Coverage patch length does not match its dimensions');
  }
}

function validateReadRegion(region: PixelRegion): void {
  integer(region.x, 'Read x');
  integer(region.y, 'Read y');
  positiveInteger(region.width, 'Read width');
  positiveInteger(region.height, 'Read height');
}

export interface Command<State> {
  readonly label?: string;
  execute(state: State): State;
}

export interface HistoryOptions {
  /** Maximum undo entries retained. Defaults to 100. */
  readonly capacity?: number;
}

interface Entry<State> {
  readonly before: State;
  readonly after: State;
  readonly label?: string;
}

export class CommandHistory<State> {
  readonly #capacity: number;
  #state: State;
  #undoStack: Entry<State>[] = [];
  #redoStack: Entry<State>[] = [];

  constructor(initialState: State, options: HistoryOptions = {}) {
    const capacity = options.capacity ?? 100;
    if (!Number.isSafeInteger(capacity) || capacity < 0) {
      throw new RangeError('History capacity must be a non-negative integer');
    }
    this.#state = initialState;
    this.#capacity = capacity;
  }

  get state(): State {
    return this.#state;
  }

  get canUndo(): boolean {
    return this.#undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.#redoStack.length > 0;
  }

  get undoCount(): number {
    return this.#undoStack.length;
  }

  get redoCount(): number {
    return this.#redoStack.length;
  }

  get nextUndoLabel(): string | undefined {
    return this.#undoStack.at(-1)?.label;
  }

  get nextRedoLabel(): string | undefined {
    return this.#redoStack.at(-1)?.label;
  }

  execute(command: Command<State>): State {
    const before = this.#state;
    const after = command.execute(before);
    this.#state = after;
    this.#redoStack = [];
    if (this.#capacity > 0 && after !== before) {
      const entry: Entry<State> =
        command.label === undefined ? { before, after } : { before, after, label: command.label };
      this.#undoStack.push(entry);
      if (this.#undoStack.length > this.#capacity) this.#undoStack.shift();
    }
    return this.#state;
  }

  undo(): State {
    const entry = this.#undoStack.pop();
    if (entry === undefined) return this.#state;
    this.#state = entry.before;
    this.#redoStack.push(entry);
    return this.#state;
  }

  redo(): State {
    const entry = this.#redoStack.pop();
    if (entry === undefined) return this.#state;
    this.#state = entry.after;
    this.#undoStack.push(entry);
    return this.#state;
  }

  clear(): void {
    this.#undoStack = [];
    this.#redoStack = [];
  }

  /** Replaces the current state and discards all history. */
  reset(state: State): void {
    this.#state = state;
    this.clear();
  }
}

import {
  invertLayerTransform,
  transformPoint,
  validateLayerTransform,
  type LayerTransform,
  type PixelLayer,
  type PixelPatch,
  type SelectionMask,
} from '@freetoshop/core-document';
import { TiledPixelStore } from '@freetoshop/pixel-storage';

export interface LevelsOptions {
  readonly inputBlack: number;
  readonly gamma: number;
  readonly inputWhite: number;
  readonly outputBlack: number;
  readonly outputWhite: number;
}

export interface HueSaturationOptions {
  /** Rotation in degrees from -180 through 180. */
  readonly hue: number;
  /** Relative saturation adjustment from -100 through 100 percent. */
  readonly saturation: number;
  /** Relative lightness adjustment from -100 through 100 percent. */
  readonly lightness: number;
}

export type PointwiseRgbFilter =
  | { readonly kind: 'contrast'; readonly amount: number }
  | { readonly kind: 'levels'; readonly options: LevelsOptions }
  | { readonly kind: 'hue-saturation'; readonly options: HueSaturationOptions }
  | { readonly kind: 'invert' }
  | { readonly kind: 'grayscale' }
  | { readonly kind: 'threshold'; readonly level: number }
  | { readonly kind: 'posterize'; readonly levels: number };

export interface FilterPatchObserver {
  readonly onPatch?: (patch: PixelPatch) => void;
  readonly onProgress?: (completedTiles: number, totalTiles: number) => void;
}

const MAX_FILTER_OUTPUT_BYTES = 512 * 1024 * 1024;
const MAX_GAUSSIAN_WORKING_BYTES = 512 * 1024 * 1024;
const MAX_GAUSSIAN_RADIUS = 100;

interface Bounds {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

type Rgb = readonly [number, number, number];

function validateLayer(layer: PixelLayer): void {
  if (!Number.isSafeInteger(layer.width) || layer.width <= 0) {
    throw new RangeError('Layer width must be a positive integer');
  }
  if (!Number.isSafeInteger(layer.height) || layer.height <= 0) {
    throw new RangeError('Layer height must be a positive integer');
  }
  const length = layer.width * layer.height * 4;
  if (
    !Number.isSafeInteger(length) ||
    layer.pixelStore.width !== layer.width ||
    layer.pixelStore.height !== layer.height
  ) {
    throw new RangeError('Layer pixel buffer length does not match its dimensions');
  }
  if (length > MAX_FILTER_OUTPUT_BYTES) {
    throw new RangeError('Filter output would exceed the allocation limit');
  }
}

function validateSelection(selection: SelectionMask | null | undefined): void {
  if (selection == null) return;
  if (!Number.isSafeInteger(selection.width) || selection.width <= 0) {
    throw new RangeError('Selection width must be a positive integer');
  }
  if (!Number.isSafeInteger(selection.height) || selection.height <= 0) {
    throw new RangeError('Selection height must be a positive integer');
  }
  if (
    selection.coverageStore.width !== selection.width ||
    selection.coverageStore.height !== selection.height
  ) {
    throw new RangeError('Selection coverage length does not match its dimensions');
  }
}

function validateContext(
  layer: PixelLayer,
  selection: SelectionMask | null | undefined,
  worldTransform: LayerTransform,
): void {
  validateLayer(layer);
  validateSelection(selection);
  validateLayerTransform(worldTransform);
}

function finite(value: number, label: string): void {
  if (!Number.isFinite(value)) throw new RangeError(`${label} must be finite`);
}

function integerInRange(value: number, minimum: number, maximum: number, label: string): void {
  if (!Number.isInteger(value) || value < minimum || value > maximum) {
    throw new RangeError(
      `${label} must be an integer between ${String(minimum)} and ${String(maximum)}`,
    );
  }
}

/**
 * Layer-space AABB of allocated pixel tiles. Null when the layer is empty
 * (fully transparent sparse). Used to avoid full-layer densify when unselected.
 */
function pixelStoreBounds(layer: PixelLayer): Bounds | null {
  let minX = layer.width;
  let minY = layer.height;
  let maxX = -1;
  let maxY = -1;
  for (const tile of layer.pixelStore.tiles()) {
    minX = Math.min(minX, tile.x);
    minY = Math.min(minY, tile.y);
    maxX = Math.max(maxX, tile.x + tile.width - 1);
    maxY = Math.max(maxY, tile.y + tile.height - 1);
  }
  if (maxX < minX || maxY < minY) return null;
  return { left: minX, top: minY, right: maxX, bottom: maxY };
}

/**
 * Document-space AABB of allocated selection tiles (may over-estimate non-zero
 * coverage but never under-estimate). Null when the selection is empty.
 */
function selectionDocumentBounds(selection: SelectionMask): Bounds | null {
  if (selection.coverageStore.defaultCoverage !== 0) {
    return { left: 0, top: 0, right: selection.width - 1, bottom: selection.height - 1 };
  }
  let minX = selection.width;
  let minY = selection.height;
  let maxX = -1;
  let maxY = -1;
  for (const tile of selection.coverageStore.tiles()) {
    minX = Math.min(minX, tile.x);
    minY = Math.min(minY, tile.y);
    maxX = Math.max(maxX, tile.x + tile.width - 1);
    maxY = Math.max(maxY, tile.y + tile.height - 1);
  }
  if (maxX < minX || maxY < minY) return null;
  return { left: minX, top: minY, right: maxX, bottom: maxY };
}

/**
 * Maps a document-space AABB into layer-local integer bounds via inverse transform
 * of the four corners, expanded by `pad` and clamped to the layer.
 */
function layerBoundsFromDocumentBounds(
  documentBounds: Bounds,
  worldTransform: LayerTransform,
  layerWidth: number,
  layerHeight: number,
  pad: number,
): Bounds | null {
  const inverse = invertLayerTransform(worldTransform);
  const corners = [
    transformPoint(inverse, documentBounds.left, documentBounds.top),
    transformPoint(inverse, documentBounds.right + 1, documentBounds.top),
    transformPoint(inverse, documentBounds.left, documentBounds.bottom + 1),
    transformPoint(inverse, documentBounds.right + 1, documentBounds.bottom + 1),
  ];
  let minX = corners[0].x;
  let minY = corners[0].y;
  let maxX = corners[0].x;
  let maxY = corners[0].y;
  for (let index = 1; index < corners.length; index += 1) {
    const corner = corners[index];
    minX = Math.min(minX, corner.x);
    minY = Math.min(minY, corner.y);
    maxX = Math.max(maxX, corner.x);
    maxY = Math.max(maxY, corner.y);
  }
  const left = Math.max(0, Math.floor(minX) - pad);
  const top = Math.max(0, Math.floor(minY) - pad);
  const right = Math.min(layerWidth - 1, Math.ceil(maxX) + pad);
  const bottom = Math.min(layerHeight - 1, Math.ceil(maxY) + pad);
  if (right < left || bottom < top) return null;
  return { left, top, right, bottom };
}

function intersectBounds(left: Bounds, right: Bounds): Bounds | null {
  const intersection = {
    left: Math.max(left.left, right.left),
    top: Math.max(left.top, right.top),
    right: Math.min(left.right, right.right),
    bottom: Math.min(left.bottom, right.bottom),
  };
  return intersection.right < intersection.left || intersection.bottom < intersection.top
    ? null
    : intersection;
}

/** Conservative document-space coverage read for a layer-space work rectangle. */
function selectionRegionForLayerBounds(
  bounds: Bounds,
  transform: LayerTransform,
  selection: SelectionMask,
): Bounds | null {
  const corners = [
    transformPoint(transform, bounds.left, bounds.top),
    transformPoint(transform, bounds.right, bounds.top),
    transformPoint(transform, bounds.left, bounds.bottom),
    transformPoint(transform, bounds.right, bounds.bottom),
  ];
  const left = Math.max(0, Math.floor(Math.min(...corners.map((point) => point.x))));
  const top = Math.max(0, Math.floor(Math.min(...corners.map((point) => point.y))));
  const right = Math.min(
    selection.width - 1,
    Math.floor(Math.max(...corners.map((point) => point.x))),
  );
  const bottom = Math.min(
    selection.height - 1,
    Math.floor(Math.max(...corners.map((point) => point.y))),
  );
  return right < left || bottom < top ? null : { left, top, right, bottom };
}

function readSelectionRegion(
  selection: SelectionMask,
  transform: LayerTransform,
  bounds: Bounds,
): { coverage: Uint8ClampedArray; region: Bounds } | null {
  const region = selectionRegionForLayerBounds(bounds, transform, selection);
  if (region === null) return null;
  return {
    coverage: selection.coverageStore.read({
      x: region.left,
      y: region.top,
      width: region.right - region.left + 1,
      height: region.bottom - region.top + 1,
    }),
    region,
  };
}

function selectionCoverage(
  selection: SelectionMask | null | undefined,
  transform: LayerTransform,
  x: number,
  y: number,
  denseCoverage?: Uint8ClampedArray | null,
  /** When denseCoverage is a sub-rectangle read, its document origin/size. */
  denseRegion?: Bounds | null,
): number {
  if (selection == null) return 1;
  const point = transformPoint(transform, x, y);
  const documentX = Math.floor(point.x);
  const documentY = Math.floor(point.y);
  if (
    documentX < 0 ||
    documentY < 0 ||
    documentX >= selection.width ||
    documentY >= selection.height
  ) {
    return 0;
  }
  if (denseCoverage && denseRegion) {
    if (
      documentX < denseRegion.left ||
      documentY < denseRegion.top ||
      documentX > denseRegion.right ||
      documentY > denseRegion.bottom
    ) {
      return 0;
    }
    const width = denseRegion.right - denseRegion.left + 1;
    return (
      (denseCoverage[(documentY - denseRegion.top) * width + (documentX - denseRegion.left)] ?? 0) /
      255
    );
  }
  const coverage = denseCoverage ?? selection.coverageStore.toContiguous();
  return (coverage[documentY * selection.width + documentX] ?? 0) / 255;
}

function include(bounds: Bounds | null, x: number, y: number): Bounds {
  if (bounds === null) return { left: x, top: y, right: x, bottom: y };
  bounds.left = Math.min(bounds.left, x);
  bounds.top = Math.min(bounds.top, y);
  bounds.right = Math.max(bounds.right, x);
  bounds.bottom = Math.max(bounds.bottom, y);
  return bounds;
}

function emptyPatch(): PixelPatch {
  return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
}

function clampByte(value: number): number {
  return Math.max(0, Math.min(255, value));
}

function applyRgb(
  layer: PixelLayer,
  operation: (red: number, green: number, blue: number) => Rgb,
  selection: SelectionMask | null | undefined,
  worldTransform: LayerTransform,
): PixelPatch {
  validateContext(layer, selection, worldTransform);

  let work: Bounds = {
    left: 0,
    top: 0,
    right: layer.width - 1,
    bottom: layer.height - 1,
  };
  let selectionCoverageBuffer: Uint8ClampedArray | null = null;
  let selectionRegion: Bounds | null = null;

  if (selection != null) {
    const documentBounds = selectionDocumentBounds(selection);
    if (documentBounds === null) return emptyPatch();
    const mapped = layerBoundsFromDocumentBounds(
      documentBounds,
      worldTransform,
      layer.width,
      layer.height,
      1,
    );
    if (mapped === null) return emptyPatch();
    const sparse = pixelStoreBounds(layer);
    if (sparse === null) return emptyPatch();
    const bounded = intersectBounds(mapped, sparse);
    if (bounded === null) return emptyPatch();
    work = bounded;
    const selectionRead = readSelectionRegion(selection, worldTransform, work);
    if (selectionRead === null) return emptyPatch();
    selectionCoverageBuffer = selectionRead.coverage;
    selectionRegion = selectionRead.region;
  } else {
    // Unselected: process only allocated sparse tiles (empty layer → no-op).
    const sparse = pixelStoreBounds(layer);
    if (sparse === null) return emptyPatch();
    work = sparse;
  }

  const regionWidth = work.right - work.left + 1;
  const regionHeight = work.bottom - work.top + 1;
  const sourcePixels = layer.pixelStore.read({
    x: work.left,
    y: work.top,
    width: regionWidth,
    height: regionHeight,
  });
  const next = new Uint8ClampedArray(sourcePixels);
  let bounds: Bounds | null = null;
  for (let y = work.top; y <= work.bottom; y += 1) {
    for (let x = work.left; x <= work.right; x += 1) {
      const coverage = selectionCoverage(
        selection,
        worldTransform,
        x,
        y,
        selectionCoverageBuffer,
        selectionRegion,
      );
      if (coverage <= 0) continue;
      const offset = ((y - work.top) * regionWidth + (x - work.left)) * 4;
      const red = sourcePixels[offset] ?? 0;
      const green = sourcePixels[offset + 1] ?? 0;
      const blue = sourcePixels[offset + 2] ?? 0;
      const adjusted = operation(red, green, blue);
      const output: Rgb = [
        Math.round(red + (adjusted[0] - red) * coverage),
        Math.round(green + (adjusted[1] - green) * coverage),
        Math.round(blue + (adjusted[2] - blue) * coverage),
      ];
      if (output[0] === red && output[1] === green && output[2] === blue) continue;
      next[offset] = output[0];
      next[offset + 1] = output[1];
      next[offset + 2] = output[2];
      bounds = include(bounds, x, y);
    }
  }
  if (bounds === null) return emptyPatch();
  // Rebuild patch from the work-region buffer.
  const patchWidth = bounds.right - bounds.left + 1;
  const patchHeight = bounds.bottom - bounds.top + 1;
  const pixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);
  for (let row = 0; row < patchHeight; row += 1) {
    const sourceY = bounds.top + row - work.top;
    const sourceX = bounds.left - work.left;
    const sourceOffset = (sourceY * regionWidth + sourceX) * 4;
    pixels.set(next.subarray(sourceOffset, sourceOffset + patchWidth * 4), row * patchWidth * 4);
  }
  return { x: bounds.left, y: bounds.top, width: patchWidth, height: patchHeight, pixels };
}

function applyRgbPatches(
  layer: PixelLayer,
  operation: (red: number, green: number, blue: number) => Rgb,
  selection: SelectionMask | null | undefined,
  worldTransform: LayerTransform,
  observer?: FilterPatchObserver,
): readonly PixelPatch[] {
  validateContext(layer, selection, worldTransform);

  let work: Bounds = {
    left: 0,
    top: 0,
    right: layer.width - 1,
    bottom: layer.height - 1,
  };
  if (selection != null) {
    const documentBounds = selectionDocumentBounds(selection);
    if (documentBounds === null) return [];
    const mapped = layerBoundsFromDocumentBounds(
      documentBounds,
      worldTransform,
      layer.width,
      layer.height,
      1,
    );
    if (mapped === null) return [];
    const sparse = pixelStoreBounds(layer);
    if (sparse === null) return [];
    const bounded = intersectBounds(mapped, sparse);
    if (bounded === null) return [];
    work = bounded;
  } else {
    const sparse = pixelStoreBounds(layer);
    if (sparse === null) return [];
    work = sparse;
  }

  const patches: PixelPatch[] = [];
  const tileSize = layer.pixelStore.tileSize;
  const startX = Math.floor(work.left / tileSize) * tileSize;
  const startY = Math.floor(work.top / tileSize) * tileSize;
  const totalTiles =
    (Math.floor(work.right / tileSize) - Math.floor(work.left / tileSize) + 1) *
    (Math.floor(work.bottom / tileSize) - Math.floor(work.top / tileSize) + 1);
  let completedTiles = 0;
  for (let tileY = startY; tileY <= work.bottom; tileY += tileSize) {
    const top = Math.max(work.top, tileY);
    const bottom = Math.min(work.bottom, tileY + tileSize - 1);
    for (let tileX = startX; tileX <= work.right; tileX += tileSize) {
      const left = Math.max(work.left, tileX);
      const right = Math.min(work.right, tileX + tileSize - 1);
      const width = right - left + 1;
      const height = bottom - top + 1;
      const source = layer.pixelStore.read({ x: left, y: top, width, height });
      const pixels = new Uint8ClampedArray(source);
      const selectionRead = selection
        ? readSelectionRegion(selection, worldTransform, { left, top, right, bottom })
        : null;
      if (selection && selectionRead === null) {
        completedTiles += 1;
        observer?.onProgress?.(completedTiles, totalTiles);
        continue;
      }
      let changed = false;
      for (let y = top; y <= bottom; y += 1) {
        for (let x = left; x <= right; x += 1) {
          const coverage = selectionCoverage(
            selection,
            worldTransform,
            x,
            y,
            selectionRead?.coverage,
            selectionRead?.region,
          );
          if (coverage <= 0) continue;
          const offset = ((y - top) * width + (x - left)) * 4;
          const red = source[offset] ?? 0;
          const green = source[offset + 1] ?? 0;
          const blue = source[offset + 2] ?? 0;
          const adjusted = operation(red, green, blue);
          const output: Rgb = [
            Math.round(red + (adjusted[0] - red) * coverage),
            Math.round(green + (adjusted[1] - green) * coverage),
            Math.round(blue + (adjusted[2] - blue) * coverage),
          ];
          if (output[0] === red && output[1] === green && output[2] === blue) continue;
          pixels[offset] = output[0];
          pixels[offset + 1] = output[1];
          pixels[offset + 2] = output[2];
          changed = true;
        }
      }
      if (changed) {
        const patch = { x: left, y: top, width, height, pixels };
        patches.push(patch);
        observer?.onPatch?.(patch);
      }
      completedTiles += 1;
      observer?.onProgress?.(completedTiles, totalTiles);
    }
  }
  return patches;
}

/** Applies a conventional contrast percentage from -100 through 100. */
export function contrast(
  layer: PixelLayer,
  amount: number,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): PixelPatch {
  finite(amount, 'Contrast amount');
  if (amount < -100 || amount > 100) {
    throw new RangeError('Contrast amount must be between -100 and 100');
  }
  const factor = (259 * (amount + 255)) / (255 * (259 - amount));
  return applyRgb(
    layer,
    (red, green, blue) => [
      clampByte(factor * (red - 128) + 128),
      clampByte(factor * (green - 128) + 128),
      clampByte(factor * (blue - 128) + 128),
    ],
    selection,
    worldTransform,
  );
}

export function levels(
  layer: PixelLayer,
  options: LevelsOptions,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): PixelPatch {
  integerInRange(options.inputBlack, 0, 254, 'Input black');
  integerInRange(options.inputWhite, 1, 255, 'Input white');
  if (options.inputBlack >= options.inputWhite) {
    throw new RangeError('Input black must be less than input white');
  }
  finite(options.gamma, 'Gamma');
  if (options.gamma <= 0 || options.gamma > 10) {
    throw new RangeError('Gamma must be greater than 0 and at most 10');
  }
  integerInRange(options.outputBlack, 0, 254, 'Output black');
  integerInRange(options.outputWhite, 1, 255, 'Output white');
  if (options.outputBlack >= options.outputWhite) {
    throw new RangeError('Output black must be less than output white');
  }
  const inputRange = options.inputWhite - options.inputBlack;
  const outputRange = options.outputWhite - options.outputBlack;
  const map = (value: number) => {
    const normalized = Math.max(0, Math.min(1, (value - options.inputBlack) / inputRange));
    return options.outputBlack + Math.pow(normalized, 1 / options.gamma) * outputRange;
  };
  return applyRgb(
    layer,
    (red, green, blue) => [map(red), map(green), map(blue)],
    selection,
    worldTransform,
  );
}

function rgbToHsl(red: number, green: number, blue: number): [number, number, number] {
  const r = red / 255;
  const g = green / 255;
  const b = blue / 255;
  const maximum = Math.max(r, g, b);
  const minimum = Math.min(r, g, b);
  const delta = maximum - minimum;
  const lightness = (maximum + minimum) / 2;
  if (delta === 0) return [0, 0, lightness];
  const saturation = delta / (1 - Math.abs(2 * lightness - 1));
  const hue =
    maximum === r
      ? 60 * (((g - b) / delta) % 6)
      : maximum === g
        ? 60 * ((b - r) / delta + 2)
        : 60 * ((r - g) / delta + 4);
  return [(hue + 360) % 360, saturation, lightness];
}

function hslToRgb(hue: number, saturation: number, lightness: number): Rgb {
  const chroma = (1 - Math.abs(2 * lightness - 1)) * saturation;
  const sector = hue / 60;
  const secondary = chroma * (1 - Math.abs((sector % 2) - 1));
  const [r, g, b]: Rgb =
    sector < 1
      ? [chroma, secondary, 0]
      : sector < 2
        ? [secondary, chroma, 0]
        : sector < 3
          ? [0, chroma, secondary]
          : sector < 4
            ? [0, secondary, chroma]
            : sector < 5
              ? [secondary, 0, chroma]
              : [chroma, 0, secondary];
  const match = lightness - chroma / 2;
  return [(r + match) * 255, (g + match) * 255, (b + match) * 255];
}

function adjustUnit(value: number, percentage: number): number {
  const amount = percentage / 100;
  return amount >= 0 ? value + (1 - value) * amount : value * (1 + amount);
}

export function hueSaturation(
  layer: PixelLayer,
  options: HueSaturationOptions,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): PixelPatch {
  finite(options.hue, 'Hue');
  finite(options.saturation, 'Saturation');
  finite(options.lightness, 'Lightness');
  if (options.hue < -180 || options.hue > 180) {
    throw new RangeError('Hue must be between -180 and 180');
  }
  if (options.saturation < -100 || options.saturation > 100) {
    throw new RangeError('Saturation must be between -100 and 100');
  }
  if (options.lightness < -100 || options.lightness > 100) {
    throw new RangeError('Lightness must be between -100 and 100');
  }
  return applyRgb(
    layer,
    (red, green, blue) => {
      const [hue, saturation, lightness] = rgbToHsl(red, green, blue);
      return hslToRgb(
        (hue + options.hue + 360) % 360,
        adjustUnit(saturation, options.saturation),
        adjustUnit(lightness, options.lightness),
      );
    },
    selection,
    worldTransform,
  );
}

export function invert(
  layer: PixelLayer,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): PixelPatch {
  return applyRgb(
    layer,
    (red, green, blue) => [255 - red, 255 - green, 255 - blue],
    selection,
    worldTransform,
  );
}

function luminance(red: number, green: number, blue: number): number {
  return 0.2126 * red + 0.7152 * green + 0.0722 * blue;
}

export function grayscale(
  layer: PixelLayer,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): PixelPatch {
  return applyRgb(
    layer,
    (red, green, blue) => {
      const gray = luminance(red, green, blue);
      return [gray, gray, gray];
    },
    selection,
    worldTransform,
  );
}

export function threshold(
  layer: PixelLayer,
  level: number,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): PixelPatch {
  integerInRange(level, 0, 255, 'Threshold level');
  return applyRgb(
    layer,
    (red, green, blue) => {
      const value = luminance(red, green, blue) >= level ? 255 : 0;
      return [value, value, value];
    },
    selection,
    worldTransform,
  );
}

export function posterize(
  layer: PixelLayer,
  numberOfLevels: number,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): PixelPatch {
  integerInRange(numberOfLevels, 2, 256, 'Posterize levels');
  const maximum = numberOfLevels - 1;
  const map = (value: number) => (Math.round((value / 255) * maximum) / maximum) * 255;
  return applyRgb(
    layer,
    (red, green, blue) => [map(red), map(green), map(blue)],
    selection,
    worldTransform,
  );
}

/** Executes pointwise RGB filters as deterministic tile-bounded output patches. */
export function pointwiseRgbFilterPatches(
  layer: PixelLayer,
  filter: PointwiseRgbFilter,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
  observer?: FilterPatchObserver,
): readonly PixelPatch[] {
  let operation: (red: number, green: number, blue: number) => Rgb;
  switch (filter.kind) {
    case 'contrast': {
      finite(filter.amount, 'Contrast amount');
      if (filter.amount < -100 || filter.amount > 100) {
        throw new RangeError('Contrast amount must be between -100 and 100');
      }
      const factor = (259 * (filter.amount + 255)) / (255 * (259 - filter.amount));
      operation = (red, green, blue) => [
        clampByte(factor * (red - 128) + 128),
        clampByte(factor * (green - 128) + 128),
        clampByte(factor * (blue - 128) + 128),
      ];
      break;
    }
    case 'levels': {
      const options = filter.options;
      integerInRange(options.inputBlack, 0, 254, 'Input black');
      integerInRange(options.inputWhite, 1, 255, 'Input white');
      if (options.inputBlack >= options.inputWhite) {
        throw new RangeError('Input black must be less than input white');
      }
      finite(options.gamma, 'Gamma');
      if (options.gamma <= 0 || options.gamma > 10) {
        throw new RangeError('Gamma must be greater than 0 and at most 10');
      }
      integerInRange(options.outputBlack, 0, 254, 'Output black');
      integerInRange(options.outputWhite, 1, 255, 'Output white');
      if (options.outputBlack >= options.outputWhite) {
        throw new RangeError('Output black must be less than output white');
      }
      const inputRange = options.inputWhite - options.inputBlack;
      const outputRange = options.outputWhite - options.outputBlack;
      const map = (value: number) => {
        const normalized = Math.max(0, Math.min(1, (value - options.inputBlack) / inputRange));
        return options.outputBlack + Math.pow(normalized, 1 / options.gamma) * outputRange;
      };
      operation = (red, green, blue) => [map(red), map(green), map(blue)];
      break;
    }
    case 'hue-saturation': {
      const options = filter.options;
      finite(options.hue, 'Hue');
      finite(options.saturation, 'Saturation');
      finite(options.lightness, 'Lightness');
      if (options.hue < -180 || options.hue > 180)
        throw new RangeError('Hue must be between -180 and 180');
      if (options.saturation < -100 || options.saturation > 100)
        throw new RangeError('Saturation must be between -100 and 100');
      if (options.lightness < -100 || options.lightness > 100)
        throw new RangeError('Lightness must be between -100 and 100');
      operation = (red, green, blue) => {
        const [hue, saturation, lightness] = rgbToHsl(red, green, blue);
        return hslToRgb(
          (hue + options.hue + 360) % 360,
          adjustUnit(saturation, options.saturation),
          adjustUnit(lightness, options.lightness),
        );
      };
      break;
    }
    case 'invert':
      operation = (red, green, blue) => [255 - red, 255 - green, 255 - blue];
      break;
    case 'grayscale':
      operation = (red, green, blue) => {
        const gray = luminance(red, green, blue);
        return [gray, gray, gray];
      };
      break;
    case 'threshold':
      integerInRange(filter.level, 0, 255, 'Threshold level');
      operation = (red, green, blue) => {
        const value = luminance(red, green, blue) >= filter.level ? 255 : 0;
        return [value, value, value];
      };
      break;
    case 'posterize': {
      integerInRange(filter.levels, 2, 256, 'Posterize levels');
      const maximum = filter.levels - 1;
      const map = (value: number) => (Math.round((value / 255) * maximum) / maximum) * 255;
      operation = (red, green, blue) => [map(red), map(green), map(blue)];
      break;
    }
  }
  return applyRgbPatches(layer, operation, selection, worldTransform, observer);
}

function gaussianKernel(radius: number): Float64Array {
  const sigma = Math.max(0.5, radius / 2);
  const kernel = new Float64Array(radius * 2 + 1);
  let sum = 0;
  for (let offset = -radius; offset <= radius; offset += 1) {
    const weight = Math.exp(-(offset * offset) / (2 * sigma * sigma));
    kernel[offset + radius] = weight;
    sum += weight;
  }
  for (let index = 0; index < kernel.length; index += 1) kernel[index] /= sum;
  return kernel;
}

function clampIndex(value: number, maximum: number): number {
  return Math.max(0, Math.min(maximum, value));
}

function blendPremultiplied(
  original: Rgb,
  originalAlpha: number,
  blurredPremultiplied: Rgb,
  blurredAlpha: number,
  coverage: number,
): readonly [number, number, number, number] {
  const sourceAlpha = originalAlpha / 255;
  const outputAlpha = sourceAlpha + (blurredAlpha - sourceAlpha) * coverage;
  const red =
    original[0] * sourceAlpha + (blurredPremultiplied[0] - original[0] * sourceAlpha) * coverage;
  const green =
    original[1] * sourceAlpha + (blurredPremultiplied[1] - original[1] * sourceAlpha) * coverage;
  const blue =
    original[2] * sourceAlpha + (blurredPremultiplied[2] - original[2] * sourceAlpha) * coverage;
  if (outputAlpha <= 0) return [0, 0, 0, 0];
  return [red / outputAlpha, green / outputAlpha, blue / outputAlpha, outputAlpha * 255];
}

/** Applies a separable Gaussian blur with edge clamping and premultiplied-alpha convolution. */
export function gaussianBlur(
  layer: PixelLayer,
  radius: number,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): PixelPatch {
  integerInRange(radius, 0, MAX_GAUSSIAN_RADIUS, 'Gaussian blur radius');
  validateContext(layer, selection, worldTransform);
  if (radius === 0) return emptyPatch();

  // Work set: sparse pixel AABB when unselected; otherwise selection AABB mapped
  // to layer and expanded by radius so the separable kernel has correct samples.
  let writeBounds: Bounds = {
    left: 0,
    top: 0,
    right: layer.width - 1,
    bottom: layer.height - 1,
  };
  let selectionCoverageBuffer: Uint8ClampedArray | null = null;
  let selectionRegion: Bounds | null = null;

  if (selection != null) {
    const documentBounds = selectionDocumentBounds(selection);
    if (documentBounds === null) return emptyPatch();
    const mapped = layerBoundsFromDocumentBounds(
      documentBounds,
      worldTransform,
      layer.width,
      layer.height,
      radius,
    );
    if (mapped === null) return emptyPatch();
    const sparse = pixelStoreBounds(layer);
    if (sparse === null) return emptyPatch();
    const influenced = {
      left: Math.max(0, sparse.left - radius),
      top: Math.max(0, sparse.top - radius),
      right: Math.min(layer.width - 1, sparse.right + radius),
      bottom: Math.min(layer.height - 1, sparse.bottom + radius),
    };
    const bounded = intersectBounds(mapped, influenced);
    if (bounded === null) return emptyPatch();
    writeBounds = bounded;
    const selectionRead = readSelectionRegion(selection, worldTransform, writeBounds);
    if (selectionRead === null) return emptyPatch();
    selectionCoverageBuffer = selectionRead.coverage;
    selectionRegion = selectionRead.region;
  } else {
    const sparse = pixelStoreBounds(layer);
    if (sparse === null) return emptyPatch();
    // Expand by radius so edge clamp has content; clamp to layer later via read.
    writeBounds = {
      left: Math.max(0, sparse.left - radius),
      top: Math.max(0, sparse.top - radius),
      right: Math.min(layer.width - 1, sparse.right + radius),
      bottom: Math.min(layer.height - 1, sparse.bottom + radius),
    };
  }

  // Read halo: write bounds expanded by radius, clamped to the layer (edge clamp).
  const readLeft = Math.max(0, writeBounds.left - radius);
  const readTop = Math.max(0, writeBounds.top - radius);
  const readRight = Math.min(layer.width - 1, writeBounds.right + radius);
  const readBottom = Math.min(layer.height - 1, writeBounds.bottom + radius);
  const readWidth = readRight - readLeft + 1;
  const readHeight = readBottom - readTop + 1;
  const pixelCount = readWidth * readHeight;
  const sourcePixels = layer.pixelStore.read({
    x: readLeft,
    y: readTop,
    width: readWidth,
    height: readHeight,
  });
  const workingBytes = pixelCount * 4 * Float32Array.BYTES_PER_ELEMENT + sourcePixels.length;
  if (!Number.isSafeInteger(workingBytes) || workingBytes > MAX_GAUSSIAN_WORKING_BYTES) {
    throw new RangeError('Gaussian blur working set would exceed the allocation limit');
  }
  const kernel = gaussianKernel(radius);
  const horizontal = new Float32Array(pixelCount * 4);

  // Map layer coords into the read buffer. write±radius is covered by the read
  // region, and edge-clamped samples stay inside [readLeft, readRight] × …
  const sampleSource = (layerX: number, layerY: number): number => {
    const clampedX = clampIndex(layerX, layer.width - 1);
    const clampedY = clampIndex(layerY, layer.height - 1);
    return ((clampedY - readTop) * readWidth + (clampedX - readLeft)) * 4;
  };

  for (let y = writeBounds.top; y <= writeBounds.bottom; y += 1) {
    for (let x = writeBounds.left; x <= writeBounds.right; x += 1) {
      const target = ((y - readTop) * readWidth + (x - readLeft)) * 4;
      for (let kernelIndex = 0; kernelIndex < kernel.length; kernelIndex += 1) {
        const sourceX = x + kernelIndex - radius;
        const source = sampleSource(sourceX, y);
        const weight = kernel[kernelIndex] ?? 0;
        const alpha = (sourcePixels[source + 3] ?? 0) / 255;
        horizontal[target] += (sourcePixels[source] ?? 0) * alpha * weight;
        horizontal[target + 1] += (sourcePixels[source + 1] ?? 0) * alpha * weight;
        horizontal[target + 2] += (sourcePixels[source + 2] ?? 0) * alpha * weight;
        horizontal[target + 3] += alpha * weight;
      }
    }
  }

  // Also need horizontal values for vertical kernel neighbors within write±radius.
  // Fill horizontal for the full read region rows that vertical pass may sample.
  for (let y = readTop; y <= readBottom; y += 1) {
    if (y >= writeBounds.top && y <= writeBounds.bottom) continue; // already filled write rows
    for (let x = writeBounds.left; x <= writeBounds.right; x += 1) {
      const target = ((y - readTop) * readWidth + (x - readLeft)) * 4;
      for (let kernelIndex = 0; kernelIndex < kernel.length; kernelIndex += 1) {
        const sourceX = x + kernelIndex - radius;
        const source = sampleSource(sourceX, y);
        const weight = kernel[kernelIndex] ?? 0;
        const alpha = (sourcePixels[source + 3] ?? 0) / 255;
        horizontal[target] += (sourcePixels[source] ?? 0) * alpha * weight;
        horizontal[target + 1] += (sourcePixels[source + 1] ?? 0) * alpha * weight;
        horizontal[target + 2] += (sourcePixels[source + 2] ?? 0) * alpha * weight;
        horizontal[target + 3] += alpha * weight;
      }
    }
  }

  let bounds: Bounds | null = null;
  const patchWidth = writeBounds.right - writeBounds.left + 1;
  const patchHeight = writeBounds.bottom - writeBounds.top + 1;
  const patchPixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);
  // Seed patch with original pixels so uncovered/unchanged stay correct.
  for (let y = writeBounds.top; y <= writeBounds.bottom; y += 1) {
    for (let x = writeBounds.left; x <= writeBounds.right; x += 1) {
      const src = sampleSource(x, y);
      const dst = ((y - writeBounds.top) * patchWidth + (x - writeBounds.left)) * 4;
      patchPixels[dst] = sourcePixels[src] ?? 0;
      patchPixels[dst + 1] = sourcePixels[src + 1] ?? 0;
      patchPixels[dst + 2] = sourcePixels[src + 2] ?? 0;
      patchPixels[dst + 3] = sourcePixels[src + 3] ?? 0;
    }
  }

  for (let y = writeBounds.top; y <= writeBounds.bottom; y += 1) {
    for (let x = writeBounds.left; x <= writeBounds.right; x += 1) {
      let red = 0;
      let green = 0;
      let blue = 0;
      let alpha = 0;
      for (let kernelIndex = 0; kernelIndex < kernel.length; kernelIndex += 1) {
        const sourceY = clampIndex(y + kernelIndex - radius, layer.height - 1);
        // Horizontal pass stored for write-column x at sourceY when sourceY is in read range.
        const hy = clampIndex(sourceY - readTop, readHeight - 1);
        const hx = clampIndex(x - readLeft, readWidth - 1);
        const source = (hy * readWidth + hx) * 4;
        const weight = kernel[kernelIndex] ?? 0;
        red += (horizontal[source] ?? 0) * weight;
        green += (horizontal[source + 1] ?? 0) * weight;
        blue += (horizontal[source + 2] ?? 0) * weight;
        alpha += (horizontal[source + 3] ?? 0) * weight;
      }
      const coverage = selectionCoverage(
        selection,
        worldTransform,
        x,
        y,
        selectionCoverageBuffer,
        selectionRegion,
      );
      if (coverage <= 0) continue;
      const src = sampleSource(x, y);
      const output = blendPremultiplied(
        [sourcePixels[src] ?? 0, sourcePixels[src + 1] ?? 0, sourcePixels[src + 2] ?? 0],
        sourcePixels[src + 3] ?? 0,
        [red, green, blue],
        alpha,
        coverage,
      );
      const rounded: readonly [number, number, number, number] = [
        Math.round(output[0]),
        Math.round(output[1]),
        Math.round(output[2]),
        Math.round(output[3]),
      ];
      if (
        rounded[0] === sourcePixels[src] &&
        rounded[1] === sourcePixels[src + 1] &&
        rounded[2] === sourcePixels[src + 2] &&
        rounded[3] === sourcePixels[src + 3]
      ) {
        continue;
      }
      const dst = ((y - writeBounds.top) * patchWidth + (x - writeBounds.left)) * 4;
      patchPixels[dst] = rounded[0];
      patchPixels[dst + 1] = rounded[1];
      patchPixels[dst + 2] = rounded[2];
      patchPixels[dst + 3] = rounded[3];
      bounds = include(bounds, x, y);
    }
  }
  if (bounds === null) return emptyPatch();
  // Trim patch to changed bounds.
  const outW = bounds.right - bounds.left + 1;
  const outH = bounds.bottom - bounds.top + 1;
  const pixels = new Uint8ClampedArray(outW * outH * 4);
  for (let row = 0; row < outH; row += 1) {
    const srcY = bounds.top + row - writeBounds.top;
    const srcX = bounds.left - writeBounds.left;
    const srcOffset = (srcY * patchWidth + srcX) * 4;
    pixels.set(patchPixels.subarray(srcOffset, srcOffset + outW * 4), row * outW * 4);
  }
  return { x: bounds.left, y: bounds.top, width: outW, height: outH, pixels };
}

/**
 * Executes Gaussian Blur as destination-tile patches. Each tile reads only its
 * radius halo and delegates to the reference kernel, then crops back to the core.
 */
export function gaussianBlurPatches(
  layer: PixelLayer,
  radius: number,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
  observer?: FilterPatchObserver,
): readonly PixelPatch[] {
  integerInRange(radius, 0, MAX_GAUSSIAN_RADIUS, 'Gaussian blur radius');
  validateContext(layer, selection, worldTransform);
  if (radius === 0) return [];

  let work: Bounds;
  if (selection != null) {
    const documentBounds = selectionDocumentBounds(selection);
    if (documentBounds === null) return [];
    const mapped = layerBoundsFromDocumentBounds(
      documentBounds,
      worldTransform,
      layer.width,
      layer.height,
      radius,
    );
    if (mapped === null) return [];
    const sparse = pixelStoreBounds(layer);
    if (sparse === null) return [];
    const influenced = {
      left: Math.max(0, sparse.left - radius),
      top: Math.max(0, sparse.top - radius),
      right: Math.min(layer.width - 1, sparse.right + radius),
      bottom: Math.min(layer.height - 1, sparse.bottom + radius),
    };
    const bounded = intersectBounds(mapped, influenced);
    if (bounded === null) return [];
    work = bounded;
  } else {
    const sparse = pixelStoreBounds(layer);
    if (sparse === null) return [];
    work = {
      left: Math.max(0, sparse.left - radius),
      top: Math.max(0, sparse.top - radius),
      right: Math.min(layer.width - 1, sparse.right + radius),
      bottom: Math.min(layer.height - 1, sparse.bottom + radius),
    };
  }

  const patches: PixelPatch[] = [];
  const tileSize = layer.pixelStore.tileSize;
  const startX = Math.floor(work.left / tileSize) * tileSize;
  const startY = Math.floor(work.top / tileSize) * tileSize;
  const totalTiles =
    (Math.floor(work.right / tileSize) - Math.floor(work.left / tileSize) + 1) *
    (Math.floor(work.bottom / tileSize) - Math.floor(work.top / tileSize) + 1);
  let completedTiles = 0;
  for (let tileY = startY; tileY <= work.bottom; tileY += tileSize) {
    const coreTop = Math.max(work.top, tileY);
    const coreBottom = Math.min(work.bottom, tileY + tileSize - 1);
    for (let tileX = startX; tileX <= work.right; tileX += tileSize) {
      const coreLeft = Math.max(work.left, tileX);
      const coreRight = Math.min(work.right, tileX + tileSize - 1);
      const sourceLeft = Math.max(0, coreLeft - radius);
      const sourceTop = Math.max(0, coreTop - radius);
      const sourceRight = Math.min(layer.width - 1, coreRight + radius);
      const sourceBottom = Math.min(layer.height - 1, coreBottom + radius);
      const sourceWidth = sourceRight - sourceLeft + 1;
      const sourceHeight = sourceBottom - sourceTop + 1;
      const sourcePixels = layer.pixelStore.read({
        x: sourceLeft,
        y: sourceTop,
        width: sourceWidth,
        height: sourceHeight,
      });
      const localWorldTransform: LayerTransform = {
        ...worldTransform,
        e: worldTransform.a * sourceLeft + worldTransform.c * sourceTop + worldTransform.e,
        f: worldTransform.b * sourceLeft + worldTransform.d * sourceTop + worldTransform.f,
      };
      const localLayer: PixelLayer = {
        ...layer,
        width: sourceWidth,
        height: sourceHeight,
        transform: localWorldTransform,
        pixelStore: TiledPixelStore.fromContiguous(
          sourceWidth,
          sourceHeight,
          sourcePixels,
          tileSize,
        ),
      };
      const local = gaussianBlur(localLayer, radius, selection, localWorldTransform);
      if (local.width === 0) {
        completedTiles += 1;
        observer?.onProgress?.(completedTiles, totalTiles);
        continue;
      }
      const coreLocalLeft = coreLeft - sourceLeft;
      const coreLocalTop = coreTop - sourceTop;
      const intersectionLeft = Math.max(local.x, coreLocalLeft);
      const intersectionTop = Math.max(local.y, coreLocalTop);
      const intersectionRight = Math.min(local.x + local.width - 1, coreRight - sourceLeft);
      const intersectionBottom = Math.min(local.y + local.height - 1, coreBottom - sourceTop);
      if (intersectionRight < intersectionLeft || intersectionBottom < intersectionTop) {
        completedTiles += 1;
        observer?.onProgress?.(completedTiles, totalTiles);
        continue;
      }
      const width = intersectionRight - intersectionLeft + 1;
      const height = intersectionBottom - intersectionTop + 1;
      const pixels = new Uint8ClampedArray(width * height * 4);
      const localPixels = new Uint8ClampedArray(local.pixels);
      for (let row = 0; row < height; row += 1) {
        const sourceOffset =
          ((intersectionTop + row - local.y) * local.width + intersectionLeft - local.x) * 4;
        pixels.set(localPixels.subarray(sourceOffset, sourceOffset + width * 4), row * width * 4);
      }
      const patch = {
        x: sourceLeft + intersectionLeft,
        y: sourceTop + intersectionTop,
        width,
        height,
        pixels,
      };
      patches.push(patch);
      observer?.onPatch?.(patch);
      completedTiles += 1;
      observer?.onProgress?.(completedTiles, totalTiles);
    }
  }
  return patches;
}

import type {
  CanvasAnchorPosition,
  ImageDocument,
  LayerTransform,
  ShapeGeometry,
} from '@freetoshop/core-document';
import type { CommandHistory } from '@freetoshop/command-history';
import type { BrushPoint, ResamplingMethod } from '@freetoshop/raster-engine';
import type { SelectionPoint } from '@freetoshop/selection-engine';
import type { FreeTransformSnapshot, TransformHandleId } from '@freetoshop/transform-engine';
import type { ViewportTransform } from '@freetoshop/renderer';

export type Toast = { id: number; message: string; tone: 'info' | 'error' };
export type Tool =
  | 'pan'
  | 'move'
  | 'transform'
  | 'crop'
  | 'select'
