      x: 4000,
      y: 4000,
      width: 32,
      height: 32,
      coverage: new Uint8ClampedArray(32 * 32).fill(200),
    }).store;
    const rightStore = TiledCoverageStore.empty(size, size, 256).write({
      x: 4016,
      y: 4016,
      width: 32,
      height: 32,
      coverage: new Uint8ClampedArray(32 * 32).fill(100),
    }).store;
    const document = createDocument({
