describe('cloneStampStroke', () => {
  const sourceLayer = createPixelLayer({
    id: 'source',
    name: 'Source',
    width: 10,
    height: 10,
    pixels: new Uint8ClampedArray(10 * 10 * 4).fill(0),
  });
  // Fill the left half with red, right half with blue for easy visual distinction.
  const sourcePixels = sourceLayer.pixelStore.toContiguous();
  for (let y = 0; y < 10; y += 1) {
    for (let x = 0; x < 5; x += 1) {
      const offset = (y * 10 + x) * 4;
      sourcePixels[offset] = 255; // red
    }
    for (let x = 5; x < 10; x += 1) {
      const offset = (y * 10 + x) * 4;
      sourcePixels[offset + 2] = 255; // blue
    }
  }
  const updatedSource = sourceLayer.pixelStore.write({
    x: 0,
    y: 0,
    width: 10,
    height: 10,
    pixels: sourcePixels,
  }).store;
  const sourceLayerWithColors = { ...sourceLayer, pixelStore: updatedSource };

  const destinationLayer = createPixelLayer({
    id: 'dest',
    name: 'Dest',
    width: 10,
    height: 10,
  });

  const identityTransform = { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 } as const;

  const baseOptions: CloneStampOptions = {
    mode: 'source-over',
    size: 5,
    hardness: 1,
    opacity: 1,
    aligned: true,
  };

  it('samples source pixels and writes to destination layer', () => {
    const patch = cloneStampStroke(
      sourceLayerWithColors,
      identityTransform,
      destinationLayer,
      [{ x: 7, y: 5 }],
      baseOptions,
      { x: 7, y: 5 },
    );
    expect(patch.width).toBeGreaterThan(0);
    expect(patch.height).toBeGreaterThan(0);
    // Should have sampled from source - source has red on left, blue on right.
    // At aligned mode with source=(7,5) and dest=(7,5), offset is 0, so we sample from (7,5)
    // which is in the blue region (x>=5).
    const hasBlue = patch.pixels.some((v, i) => i % 4 === 2 && v === 255);
    expect(hasBlue).toBe(true);
  });

  it('preserves offset in aligned mode across multiple dabs', () => {
    const patch = cloneStampStroke(
      sourceLayerWithColors,
      identityTransform,
      destinationLayer,
      [
        { x: 7, y: 5 },
        { x: 8, y: 5 },
      ],
      baseOptions,
      { x: 7, y: 5 },
    );
    expect(patch.width).toBeGreaterThan(0);
    // Both dabs should use the same offset (0) from source point.
    const hasBlue = patch.pixels.some((v, i) => i % 4 === 2 && v === 255);
    expect(hasBlue).toBe(true);
  });

  it('re-samples from source origin in unaligned mode', () => {
    const unalignedOptions: CloneStampOptions = { ...baseOptions, aligned: false };
    const patch = cloneStampStroke(
      sourceLayerWithColors,
      identityTransform,
      destinationLayer,
      [
        { x: 7, y: 5 },
        { x: 8, y: 5 },
      ],
      unalignedOptions,
      { x: 7, y: 5 },
    );
    expect(patch.width).toBeGreaterThan(0);
    // In unaligned mode, every dab samples from source point (7,5) which is blue.
    const hasBlue = patch.pixels.some((v, i) => i % 4 === 2 && v === 255);
    expect(hasBlue).toBe(true);
  });

  it('returns a no-op for empty points', () => {
    const patch = cloneStampStroke(
      sourceLayerWithColors,
      identityTransform,
      destinationLayer,
      [],
      baseOptions,
      { x: 5, y: 5 },
    );
    expect(patch).toEqual({
      x: 0,
      y: 0,
      width: 0,
      height: 0,
      pixels: new Uint8ClampedArray(),
    });
  });

  it('validates brush size and hardness', () => {
    expect(() =>
      cloneStampStroke(
        sourceLayerWithColors,
        identityTransform,
        destinationLayer,
        [{ x: 5, y: 5 }],
        { ...baseOptions, size: 0 },
        { x: 5, y: 5 },
      ),
    ).toThrow('Brush size must be greater than 0');
    expect(() =>
      cloneStampStroke(
        sourceLayerWithColors,
        identityTransform,
        destinationLayer,
        [{ x: 5, y: 5 }],
        { ...baseOptions, hardness: 2 },
        { x: 5, y: 5 },
      ),
    ).toThrow('Clone stamp brush hardness must be between 0 and 1');
  });

  it('handles pressure correctly', () => {
    const patch = cloneStampStroke(
      sourceLayerWithColors,
      identityTransform,
      destinationLayer,
      [{ x: 7, y: 5, pressure: 0.5 }],
      { ...baseOptions, opacity: 0.5 },
      { x: 7, y: 5 },
    );
    expect(patch.width).toBeGreaterThan(0);
  });

  it('is tile-local on large sparse layers', () => {
    const hugeSource = createPixelLayer({
      id: 'huge-source',
      name: 'Huge Source',
      width: 4096,
      height: 4096,
    });
    const hugeDest = createPixelLayer({
      id: 'huge-dest',
      name: 'Huge Dest',
      width: 4096,
      height: 4096,
    });
    const beforeBytes = hugeDest.pixelStore.allocatedByteLength;
    const patch = cloneStampStroke(
      hugeSource,
      identityTransform,
      hugeDest,
      [{ x: 2000, y: 2000 }],
      { ...baseOptions, size: 16, hardness: 0.85, opacity: 0.9 },
      { x: 2000, y: 2000 },
    );
    expect(patch.width).toBeGreaterThan(0);
    expect(patch.width * patch.height).toBeLessThan(64 * 64);
    // Source layer remains sparse.
    expect(hugeSource.pixelStore.allocatedByteLength).toBe(beforeBytes);
    expect(hugeDest.pixelStore.allocatedByteLength).toBe(beforeBytes);
  });
});

