const regionLeft = strokeBounds.left;
const regionTop = strokeBounds.top;
const regionWidth = strokeBounds.right - strokeBounds.left + 1;
const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
console.log('region:', { regionLeft, regionTop, regionWidth, regionHeight });

// Read from destination
const next = destinationLayer.pixelStore.read({
  x: regionLeft,
  y: regionTop,
  width: regionWidth,
  height: regionHeight,
});
console.log('next length:', next.length);
console.log('next all zeros:', next.every(v => v === 0));

// sourceBounds
const sourceBounds = { left: 5, top: 3, right: 9, bottom: 7 };
const sourceReadWidth = sourceBounds.right - sourceBounds.left + 1;
const sourceReadHeight = sourceBounds.bottom - sourceBounds.top + 1;
console.log('source bounds:', sourceBounds, 'read size:', sourceReadWidth, sourceReadHeight);

const sourceBuffer = sourceLayerWithColors.pixelStore.read({
  x: sourceBounds.left,
  y: sourceBounds.top,
  width: sourceReadWidth,
  height: sourceReadHeight,
});
console.log('source buffer[48]:', sourceBuffer[48], 'source buffer[50]:', sourceBuffer[50]);

// Loop
let changedBounds = null;
const dab = { x: 7, y: 5, pressure: 1 };
for (let y = strokeBounds.top; y <= strokeBounds.bottom; y++) {
  for (let x = strokeBounds.left; x <= strokeBounds.right; x++) {
    const dx = x - dab.x;
    const dy = y - dab.y;
    const distance = Math.hypot(dx, dy);
    const falloff = distance <= radius ? (distance <= radius * hardness ? 1 : 1 - (distance - radius * hardness) / (radius - radius * hardness)) : 0;
    if (falloff <= 0) continue;

    const docSourceX = sourcePoint.x + (dab.x - firstPoint.x);
    const docSourceY = sourcePoint.y + (dab.y - firstPoint.y);
    const sourceLocalX = Math.round(docSourceX);
    const sourceLocalY = Math.round(docSourceY);
    const bufferX = sourceLocalX - sourceBounds.left;
    const bufferY = sourceLocalY - sourceBounds.top;
    const sourceOffset = (bufferY * sourceReadWidth + bufferX) * 4;

    const sampledRed = sourceBuffer[sourceOffset];
    const sampledGreen = sourceBuffer[sourceOffset + 1];
    const sampledBlue = sourceBuffer[sourceOffset + 2];
    const sampledAlpha = sourceBuffer[sourceOffset + 3];

    const offset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
    const before = [next[offset], next[offset + 1], next[offset + 2], next[offset + 3]];

    // compositeSourceOver
    const sourceAlpha = (sampledAlpha / 255) * falloff;
    const destinationAlpha = (next[offset + 3] ?? 0) / 255;
    const outputAlpha = sourceAlpha + destinationAlpha * (1 - sourceAlpha);
    if (outputAlpha === 0) continue;
    next[offset] = Math.round((sampledRed * sourceAlpha + (before[0] ?? 0) * destinationAlpha * (1 - sourceAlpha)) / outputAlpha);
    next[offset + 1] = Math.round((sampledGreen * sourceAlpha + (before[1] ?? 0) * destinationAlpha * (1 - sourceAlpha)) / outputAlpha);
    next[offset + 2] = Math.round((sampledBlue * sourceAlpha + (before[2] ?? 0) * destinationAlpha * (1 - sourceAlpha)) / outputAlpha);
    next[offset + 3] = Math.round(outputAlpha * 255);

    if (before[0] !== next[offset] || before[1] !== next[offset + 1] || before[2] !== next[offset + 2] || before[3] !== next[offset + 3]) {
      changedBounds = changedBounds ? {
        left: Math.min(changedBounds.left, x),
        top: Math.min(changedBounds.top, y),
        right: Math.max(changedBounds.right, x),
        bottom: Math.max(changedBounds.bottom, y),
      } : { left: x, top: y, right: x, bottom: y };
    }
  }
}
