test('clone stamp samples source and paints into destination layer', async ({ page }) => {
  // Create a source image with a red-to-blue gradient.
  const bytes = await page.evaluate(async () => {
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 32;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas unavailable');
    for (let y = 0; y < 32; y++) {
      for (let x = 0; x < 32; x++) {
        const isLeft = x < 16;
        context.fillStyle = isLeft ? 'rgb(255,0,0)' : 'rgb(0,0,255)';
        context.fillRect(x, y, 1, 1);
      }
    }
    const blob = await new Promise<Blob>((resolve, reject) =>
      canvas.toBlob(
        (value) => (value ? resolve(value) : reject(new Error('PNG failed'))),
        'image/png',
      ),
    );
    return [...new Uint8Array(await blob.arrayBuffer())];
  });
  const sourceBuffer = Buffer.from(bytes);

  await page.getByLabel('Open image file').setInputFiles({
    name: 'clone-source.png',
    mimeType: 'image/png',
    buffer: sourceBuffer,
  });

  // Select the clone stamp tool.
  await page.getByRole('button', { name: 'Clone stamp' }).click();
  await expect(page.getByLabel('Tool options')).toContainText('Clone Stamp');
  await expect(page.getByLabel('Tool options')).toContainText(
    'Alt-click on source layer to set clone point',
  );

  // Set the clone source by Alt-clicking on the right (blue) side.
  const sourcePoint = await documentPoint(page, 24, 16);
  await page.mouse.move(sourcePoint.x, sourcePoint.y);
  await page.keyboard.down('Alt');
  await page.mouse.down();
  await page.mouse.up();
  await page.keyboard.up('Alt');
  await expect(page.getByLabel('Tool options')).toContainText('Clone stamp active');

  // Paint on the left (red) side — should clone blue pixels.
  await page.getByLabel('Brush size').fill('4');
  const paintPoint = await documentPoint(page, 8, 16);
  await page.mouse.move(paintPoint.x, paintPoint.y);
  await page.mouse.down();
  await page.mouse.up();

  // Export and verify: the left side should now have blue pixels where we painted.
  expect(await exportedPixel(page, 8, 16)).toEqual([0, 0, 255, 255]);
  // The right side (source area) should still be blue.
  expect(await exportedPixel(page, 24, 16)).toEqual([0, 0, 255, 255]);
});

