test('clone stamp shows error without source and can undo', async ({ page }) => {
  // Create a red source layer.
  const bytes = await page.evaluate(async () => {
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 32;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas unavailable');
    context.fillStyle = 'rgb(255,0,0)';
    context.fillRect(0, 0, 32, 32);
    const blob = await new Promise<Blob>((resolve, reject) =>
      canvas.toBlob(
        (value) => (value ? resolve(value) : reject(new Error('PNG failed'))),
        'image/png',
      ),
    );
    return [...new Uint8Array(await blob.arrayBuffer())];
  });
  const sourceBuffer = Buffer.from(bytes);

  await page.getByLabel('Open image file').setInputFiles({
    name: 'clone-red.png',
    mimeType: 'image/png',
    buffer: sourceBuffer,
  });

  await page.getByRole('button', { name: 'Clone stamp' }).click();

  // Try painting without setting a source — should show error.
  const point = await documentPoint(page, 16, 16);
  await page.mouse.move(point.x, point.y);
  await page.mouse.down();
  await page.mouse.up();
  await expect(page.getByText('Set a clone source with Alt-click first')).toBeVisible();

  // Now set source on the red layer and paint on white background.
  // First create a white canvas to paint onto by opening a second image.
  const whiteBytes = await page.evaluate(async () => {
    const canvas = document.createElement('canvas');
    canvas.width = 32;
    canvas.height = 32;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Canvas unavailable');
    context.fillStyle = 'rgb(100,100,100)';
    context.fillRect(0, 0, 32, 32);
    const blob = await new Promise<Blob>((resolve, reject) =>
      canvas.toBlob(
        (value) => (value ? resolve(value) : reject(new Error('PNG failed'))),
        'image/png',
      ),
    );
    return [...new Uint8Array(await blob.arrayBuffer())];
  });

  await page.getByLabel('Open image file').setInputFiles({
    name: 'clone-gray.png',
    mimeType: 'image/png',
    buffer: Buffer.from(whiteBytes),
  });

  // Set source on the red layer (it should be the first layer now).
  await page.mouse.move(point.x, point.y);
  await page.keyboard.down('Alt');
  await page.mouse.down();
  await page.mouse.up();
  await page.keyboard.up('Alt');

  await page.getByLabel('Brush size').fill('4');
  await page.mouse.move(point.x, point.y);
  await page.mouse.down();
  await page.mouse.up();

  // Verify paint happened — should now be red, not gray.
  expect(await exportedPixel(page, 16, 16)).toEqual([255, 0, 0, 255]);

  // Undo should revert to gray.
  await page.getByRole('button', { name: 'Undo' }).click();
  expect(await exportedPixel(page, 16, 16)).toEqual([100, 100, 100, 255]);
});

